// NBR #1369 — computePayloadByteSegmentation
// Segments byte array into contiguous regions based on value threshold
function computePayloadByteSegmentation(bytes, opts) {
  if (!bytes || bytes.length === 0) return { segments: [], count: 0 };
  const threshold = (opts && opts.threshold !== undefined) ? opts.threshold : 128;
  const segments = [];
  let current = null;
  for (let i = 0; i < bytes.length; i++) {
    const above = bytes[i] >= threshold;
    if (current === null || current.above !== above) {
      if (current) segments.push(current);
      current = { start: i, end: i, above, length: 1 };
    } else {
      current.end = i;
      current.length++;
    }
  }
  if (current) segments.push(current);
  return { segments, count: segments.length };
}

// NBR #1370 — createDecodeResultEventEmitter
// Simple synchronous event emitter for decode pipeline events
function createDecodeResultEventEmitter() {
  const listeners = new Map();
  return {
    on(event, fn) {
      if (!listeners.has(event)) listeners.set(event, []);
      listeners.get(event).push(fn);
    },
    off(event, fn) {
      if (!listeners.has(event)) return;
      const arr = listeners.get(event);
      const idx = arr.indexOf(fn);
      if (idx >= 0) arr.splice(idx, 1);
    },
    emit(event, data) {
      if (!listeners.has(event)) return;
      for (const fn of listeners.get(event)) fn(data);
    },
    listenerCount(event) {
      return listeners.has(event) ? listeners.get(event).length : 0;
    },
    removeAll(event) {
      if (event) listeners.delete(event);
      else listeners.clear();
    }
  };
}

// NBR #1371 — computePayloadByteHuffmanFreq
// Computes byte frequencies suitable for Huffman tree construction
function computePayloadByteHuffmanFreq(bytes, opts) {
  if (!bytes || bytes.length === 0) return { frequencies: [], totalSymbols: 0, uniqueSymbols: 0 };
  const counts = new Array(256).fill(0);
  for (let i = 0; i < bytes.length; i++) counts[bytes[i]]++;
  const frequencies = [];
  for (let i = 0; i < 256; i++) {
    if (counts[i] > 0) frequencies.push({ symbol: i, count: counts[i], probability: counts[i] / bytes.length });
  }
  frequencies.sort((a, b) => b.count - a.count);
  return { frequencies, totalSymbols: bytes.length, uniqueSymbols: frequencies.length };
}

// NBR #1372 — createConfigDecodeRateLimiter
// Token bucket rate limiter for decode operations
function createConfigDecodeRateLimiter(opts) {
  const capacity = (opts && opts.capacity !== undefined) ? opts.capacity : 10;
  const refillRate = (opts && opts.refillRate !== undefined) ? opts.refillRate : 1; // tokens per second
  let tokens = capacity;
  let lastRefill = Date.now();
  return {
    tryAcquire(count) {
      const c = count !== undefined ? count : 1;
      const now = Date.now();
      const elapsed = (now - lastRefill) / 1000;
      tokens = Math.min(capacity, tokens + elapsed * refillRate);
      lastRefill = now;
      if (tokens >= c) { tokens -= c; return true; }
      return false;
    },
    getTokens() { return tokens; },
    getCapacity() { return capacity; },
    reset() { tokens = capacity; lastRefill = Date.now(); }
  };
}

// NBR #1373 — computePayloadBytePackBits
// Simple PackBits-style RLE compression of byte array
function computePayloadBytePackBits(bytes, opts) {
  if (!bytes || bytes.length === 0) return { packed: [], ratio: 1, originalSize: 0 };
  const packed = [];
  let i = 0;
  while (i < bytes.length) {
    // Check for run
    let runLen = 1;
    while (i + runLen < bytes.length && bytes[i + runLen] === bytes[i] && runLen < 128) runLen++;
    if (runLen >= 3) {
      packed.push(257 - runLen); // negative count marker
      packed.push(bytes[i]);
      i += runLen;
    } else {
      // Literal run
      let litStart = i;
      let litLen = 0;
      while (i + litLen < bytes.length && litLen < 128) {
        let nextRun = 1;
        while (i + litLen + nextRun < bytes.length && bytes[i + litLen + nextRun] === bytes[i + litLen] && nextRun < 128) nextRun++;
        if (nextRun >= 3) break;
        litLen++;
      }
      if (litLen === 0) litLen = 1;
      packed.push(litLen - 1);
      for (let j = 0; j < litLen; j++) packed.push(bytes[i + j]);
      i += litLen;
    }
  }
  return { packed, ratio: packed.length / bytes.length, originalSize: bytes.length };
}

// NBR #1374 — createDecodeResultTrie
// Trie (prefix tree) for string-based key lookups
function createDecodeResultTrie() {
  const root = { children: {}, value: undefined, isEnd: false };
  let count = 0;
  return {
    insert(key, value) {
      let node = root;
      for (const ch of key) {
        if (!node.children[ch]) node.children[ch] = { children: {}, value: undefined, isEnd: false };
        node = node.children[ch];
      }
      if (!node.isEnd) count++;
      node.isEnd = true;
      node.value = value;
    },
    search(key) {
      let node = root;
      for (const ch of key) {
        if (!node.children[ch]) return undefined;
        node = node.children[ch];
      }
      return node.isEnd ? node.value : undefined;
    },
    hasPrefix(prefix) {
      let node = root;
      for (const ch of prefix) {
        if (!node.children[ch]) return false;
        node = node.children[ch];
      }
      return true;
    },
    size() { return count; }
  };
}

// NBR #1375 — computePayloadByteAutoCorrelation
// Computes autocorrelation of byte array at specified lags
function computePayloadByteAutoCorrelation(bytes, opts) {
  if (!bytes || bytes.length < 2) return { correlations: [], dominantLag: 0 };
  const maxLag = (opts && opts.maxLag !== undefined) ? opts.maxLag : Math.min(bytes.length - 1, 32);
  let mean = 0;
  for (let i = 0; i < bytes.length; i++) mean += bytes[i];
  mean /= bytes.length;
  let variance = 0;
  for (let i = 0; i < bytes.length; i++) variance += (bytes[i] - mean) * (bytes[i] - mean);
  if (variance === 0) return { correlations: new Array(maxLag + 1).fill(0), dominantLag: 0 };
  const correlations = [];
  let bestLag = 0;
  let bestCorr = -Infinity;
  for (let lag = 0; lag <= maxLag; lag++) {
    let sum = 0;
    for (let i = 0; i < bytes.length - lag; i++) {
      sum += (bytes[i] - mean) * (bytes[i + lag] - mean);
    }
    const c = sum / variance;
    correlations.push(c);
    if (lag > 0 && c > bestCorr) { bestCorr = c; bestLag = lag; }
  }
  return { correlations, dominantLag: bestLag };
}

// NBR #1376 — createConfigDecodeMetrics
// Metrics collector for decode operations — counters, gauges, histograms
function createConfigDecodeMetrics() {
  const counters = new Map();
  const gauges = new Map();
  const histograms = new Map();
  return {
    increment(name, value) { counters.set(name, (counters.get(name) || 0) + (value !== undefined ? value : 1)); },
    getCounter(name) { return counters.get(name) || 0; },
    setGauge(name, value) { gauges.set(name, value); },
    getGauge(name) { return gauges.get(name) || 0; },
    recordHistogram(name, value) {
      if (!histograms.has(name)) histograms.set(name, []);
      histograms.get(name).push(value);
    },
    getHistogram(name) { return histograms.get(name) || []; },
    snapshot() {
      const snap = { counters: {}, gauges: {}, histograms: {} };
      counters.forEach((v, k) => { snap.counters[k] = v; });
      gauges.forEach((v, k) => { snap.gauges[k] = v; });
      histograms.forEach((v, k) => { snap.histograms[k] = v.slice(); });
      return snap;
    },
    reset() { counters.clear(); gauges.clear(); histograms.clear(); }
  };
}

// NBR #1377 — computePayloadByteBitPlane
// Extracts individual bit planes from byte array
function computePayloadByteBitPlane(bytes, opts) {
  if (!bytes || bytes.length === 0) return { planes: [], planeCount: 0 };
  const bitIndex = (opts && opts.bitIndex !== undefined) ? opts.bitIndex : 7; // MSB by default
  const plane = new Uint8Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) {
    plane[i] = (bytes[i] >> bitIndex) & 1;
  }
  let onesCount = 0;
  for (let i = 0; i < plane.length; i++) onesCount += plane[i];
  return { plane: Array.from(plane), onesRatio: onesCount / plane.length, bitIndex };
}

// NBR #1378 — createDecodeResultBloomFilter
// Probabilistic set membership using multiple hash functions
function createDecodeResultBloomFilter(opts) {
  const size = (opts && opts.size !== undefined) ? opts.size : 1024;
  const hashCount = (opts && opts.hashCount !== undefined) ? opts.hashCount : 3;
  const bits = new Uint8Array(Math.ceil(size / 8));
  let count = 0;
  function hash(str, seed) {
    let h = seed;
    for (let i = 0; i < str.length; i++) {
      h = ((h << 5) + h + str.charCodeAt(i)) & 0x7FFFFFFF;
    }
    return h % size;
  }
  return {
    add(item) {
      const s = String(item);
      for (let i = 0; i < hashCount; i++) {
        const idx = hash(s, i * 0x9E3779B9);
        bits[idx >>> 3] |= (1 << (idx & 7));
      }
      count++;
    },
    mightContain(item) {
      const s = String(item);
      for (let i = 0; i < hashCount; i++) {
        const idx = hash(s, i * 0x9E3779B9);
        if (!(bits[idx >>> 3] & (1 << (idx & 7)))) return false;
      }
      return true;
    },
    count() { return count; },
    falsePositiveRate() {
      let setBits = 0;
      for (let i = 0; i < bits.length; i++) {
        let b = bits[i];
        while (b) { setBits += b & 1; b >>= 1; }
      }
      const fillRatio = setBits / size;
      return Math.pow(fillRatio, hashCount);
    }
  };
}

// NBR #1379 — computePayloadByteMedianFilter
// 1D median filter for byte array denoising
function computePayloadByteMedianFilter(bytes, opts) {
  if (!bytes || bytes.length === 0) return { filtered: [], windowSize: 0 };
  const windowSize = (opts && opts.windowSize !== undefined) ? opts.windowSize : 3;
  const half = Math.floor(windowSize / 2);
  const filtered = new Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) {
    const window = [];
    for (let j = i - half; j <= i + half; j++) {
      if (j >= 0 && j < bytes.length) window.push(bytes[j]);
    }
    window.sort((a, b) => a - b);
    filtered[i] = window[Math.floor(window.length / 2)];
  }
  return { filtered, windowSize };
}

// NBR #1380 — createConfigDecodeObjectPool
// Generic object pool with factory, acquire, release pattern
function createConfigDecodeObjectPool(opts) {
  const factory = (opts && opts.factory) || (() => ({}));
  const maxSize = (opts && opts.maxSize !== undefined) ? opts.maxSize : 20;
  const pool = [];
  let created = 0;
  let acquired = 0;
  return {
    acquire() {
      acquired++;
      if (pool.length > 0) return pool.pop();
      created++;
      return factory();
    },
    release(obj) {
      if (pool.length < maxSize) pool.push(obj);
    },
    available() { return pool.length; },
    stats() { return { created, acquired, poolSize: pool.length, maxSize }; }
  };
}

// NBR #1381 — computePayloadByteMinHash
// MinHash signature for approximate Jaccard similarity of byte sets
function computePayloadByteMinHash(bytes, opts) {
  if (!bytes || bytes.length === 0) return { signature: [], numHashes: 0 };
  const numHashes = (opts && opts.numHashes !== undefined) ? opts.numHashes : 16;
  const signature = new Array(numHashes).fill(Infinity);
  const uniqueBytes = new Set(bytes);
  for (const byte of uniqueBytes) {
    for (let h = 0; h < numHashes; h++) {
      const hashVal = ((byte * (h * 2654435761 + 1)) ^ (h * 0x5BD1E995)) & 0x7FFFFFFF;
      if (hashVal < signature[h]) signature[h] = hashVal;
    }
  }
  return { signature, numHashes };
}

// NBR #1382 — createDecodeResultVersionedMap
// Map that tracks version history of values for each key
function createDecodeResultVersionedMap() {
  const store = new Map();
  return {
    set(key, value) {
      if (!store.has(key)) store.set(key, []);
      store.get(key).push({ value, timestamp: Date.now(), version: store.get(key).length + 1 });
    },
    get(key) {
      if (!store.has(key)) return undefined;
      const hist = store.get(key);
      return hist[hist.length - 1].value;
    },
    getVersion(key, version) {
      if (!store.has(key)) return undefined;
      const hist = store.get(key);
      if (version < 1 || version > hist.length) return undefined;
      return hist[version - 1].value;
    },
    getHistory(key) {
      return store.has(key) ? store.get(key).slice() : [];
    },
    currentVersion(key) {
      return store.has(key) ? store.get(key).length : 0;
    },
    size() { return store.size; }
  };
}

// NBR #1383 — computePayloadByteInterquartileRange
// Computes IQR and quartile statistics for byte arrays
function computePayloadByteInterquartileRange(bytes, opts) {
  if (!bytes || bytes.length === 0) return { q1: 0, q2: 0, q3: 0, iqr: 0, lowerFence: 0, upperFence: 0 };
  const sorted = Array.from(bytes).sort((a, b) => a - b);
  const n = sorted.length;
  const q = (p) => {
    const pos = p * (n - 1);
    const lo = Math.floor(pos);
    const hi = Math.ceil(pos);
    return lo === hi ? sorted[lo] : sorted[lo] + (sorted[hi] - sorted[lo]) * (pos - lo);
  };
  const q1 = q(0.25), q2 = q(0.5), q3 = q(0.75);
  const iqr = q3 - q1;
  const k = (opts && opts.k !== undefined) ? opts.k : 1.5;
  return { q1, q2, q3, iqr, lowerFence: q1 - k * iqr, upperFence: q3 + k * iqr };
}

// NBR #1384 — createConfigDecodeStateMachine
// Finite state machine for decode pipeline state management
function createConfigDecodeStateMachine(opts) {
  const transitions = (opts && opts.transitions) || {};
  let currentState = (opts && opts.initial) || "idle";
  const history = [currentState];
  return {
    getState() { return currentState; },
    transition(event) {
      const key = currentState + ":" + event;
      if (transitions[key]) {
        currentState = transitions[key];
        history.push(currentState);
        return true;
      }
      return false;
    },
    canTransition(event) { return !!transitions[currentState + ":" + event]; },
    getHistory() { return history.slice(); },
    reset() { currentState = (opts && opts.initial) || "idle"; history.length = 0; history.push(currentState); }
  };
}

// NBR #1385 — computePayloadByteCrossEntropy
// Computes cross-entropy between byte distribution and uniform reference
function computePayloadByteCrossEntropy(bytes, opts) {
  if (!bytes || bytes.length === 0) return { crossEntropy: 0, entropy: 0, klDivergence: 0 };
  const counts = new Array(256).fill(0);
  for (let i = 0; i < bytes.length; i++) counts[bytes[i]]++;
  let entropy = 0;
  const uniformP = 1 / 256;
  let crossEntropy = 0;
  for (let i = 0; i < 256; i++) {
    const p = counts[i] / bytes.length;
    if (p > 0) {
      entropy -= p * Math.log2(p);
      crossEntropy -= p * Math.log2(uniformP);
    }
  }
  return { crossEntropy, entropy, klDivergence: crossEntropy - entropy };
}

// NBR #1386 — createDecodeResultIntervalTree
// Interval tree for range-based lookups (simplified array-based)
function createDecodeResultIntervalTree() {
  const intervals = [];
  return {
    insert(low, high, data) {
      intervals.push({ low, high, data });
      intervals.sort((a, b) => a.low - b.low);
    },
    query(point) {
      const results = [];
      for (const iv of intervals) {
        if (iv.low <= point && point <= iv.high) results.push(iv);
      }
      return results;
    },
    queryRange(low, high) {
      const results = [];
      for (const iv of intervals) {
        if (iv.low <= high && iv.high >= low) results.push(iv);
      }
      return results;
    },
    size() { return intervals.length; },
    all() { return intervals.slice(); }
  };
}

// NBR #1387 — computePayloadByteRLECompress
// Standard run-length encoding of byte array
function computePayloadByteRLECompress(bytes, opts) {
  if (!bytes || bytes.length === 0) return { runs: [], totalRuns: 0, compressionRatio: 1 };
  const runs = [];
  let i = 0;
  while (i < bytes.length) {
    let runLen = 1;
    while (i + runLen < bytes.length && bytes[i + runLen] === bytes[i] && runLen < 255) runLen++;
    runs.push({ value: bytes[i], count: runLen });
    i += runLen;
  }
  return { runs, totalRuns: runs.length, compressionRatio: (runs.length * 2) / bytes.length };
}

// NBR #1388 — createConfigDecodeBarrier
// Synchronization barrier — collects N results before releasing
function createConfigDecodeBarrier(opts) {
  const count = (opts && opts.count !== undefined) ? opts.count : 2;
  let collected = [];
  let released = false;
  return {
    arrive(value) {
      if (released) return;
      collected.push(value);
      if (collected.length >= count) released = true;
    },
    isReleased() { return released; },
    getResults() { return collected.slice(); },
    pending() { return Math.max(0, count - collected.length); },
    reset() { collected = []; released = false; }
  };
}

// NBR #1389 — computePayloadByteDifferentialCoding
// Differential (delta) encoding of byte array
function computePayloadByteDifferentialCoding(bytes, opts) {
  if (!bytes || bytes.length === 0) return { deltas: [], canRecover: true };
  const deltas = [bytes[0]]; // first value stored as-is
  for (let i = 1; i < bytes.length; i++) {
    deltas.push(bytes[i] - bytes[i - 1]);
  }
  // Compute entropy reduction estimate
  let origRange = 0, deltaRange = 0;
  for (let i = 0; i < bytes.length; i++) origRange = Math.max(origRange, Math.abs(bytes[i]));
  for (let i = 0; i < deltas.length; i++) deltaRange = Math.max(deltaRange, Math.abs(deltas[i]));
  return { deltas, canRecover: true, maxDelta: deltaRange, maxOriginal: origRange };
}

// NBR #1390 — createDecodeResultPubSub
// Publish-subscribe with topic-based routing
function createDecodeResultPubSub() {
  const subscribers = new Map();
  let messageCount = 0;
  return {
    subscribe(topic, fn) {
      if (!subscribers.has(topic)) subscribers.set(topic, new Set());
      subscribers.get(topic).add(fn);
      return () => subscribers.get(topic).delete(fn); // unsubscribe fn
    },
    publish(topic, data) {
      messageCount++;
      if (!subscribers.has(topic)) return 0;
      let delivered = 0;
      for (const fn of subscribers.get(topic)) { fn(data); delivered++; }
      return delivered;
    },
    subscriberCount(topic) {
      return subscribers.has(topic) ? subscribers.get(topic).size : 0;
    },
    totalMessages() { return messageCount; },
    topics() { return Array.from(subscribers.keys()); }
  };
}

// NBR #1391 — computePayloadByteSpectralFlatness
// Spectral flatness (Wiener entropy) — ratio of geometric to arithmetic mean of power spectrum
function computePayloadByteSpectralFlatness(bytes, opts) {
  if (!bytes || bytes.length < 2) return { flatness: 0, isNoisy: false };
  // Simple power spectrum via squared differences
  const n = bytes.length;
  const power = [];
  for (let i = 0; i < n - 1; i++) {
    const d = bytes[i + 1] - bytes[i];
    power.push(d * d + 1); // +1 to avoid log(0)
  }
  let logSum = 0, sum = 0;
  for (let i = 0; i < power.length; i++) {
    logSum += Math.log(power[i]);
    sum += power[i];
  }
  const geometricMean = Math.exp(logSum / power.length);
  const arithmeticMean = sum / power.length;
  const flatness = arithmeticMean > 0 ? geometricMean / arithmeticMean : 0;
  return { flatness, isNoisy: flatness > 0.8 };
}

// NBR #1392 — createConfigDecodeMiddleware
// Middleware pipeline — chain of transform functions applied in order
function createConfigDecodeMiddleware() {
  const stack = [];
  return {
    use(fn) { stack.push(fn); },
    execute(input) {
      let result = input;
      for (const fn of stack) {
        result = fn(result);
        if (result === undefined || result === null) break;
      }
      return result;
    },
    count() { return stack.length; },
    clear() { stack.length = 0; }
  };
}

// NBR #1393 — computePayloadByteHistogramEqualization
// Histogram equalization to redistribute byte values uniformly
function computePayloadByteHistogramEqualization(bytes, opts) {
  if (!bytes || bytes.length === 0) return { equalized: [], histogram: [] };
  const hist = new Array(256).fill(0);
  for (let i = 0; i < bytes.length; i++) hist[bytes[i]]++;
  // Compute CDF
  const cdf = new Array(256);
  cdf[0] = hist[0];
  for (let i = 1; i < 256; i++) cdf[i] = cdf[i - 1] + hist[i];
  const cdfMin = cdf.find(v => v > 0);
  const equalized = new Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) {
    equalized[i] = Math.round(((cdf[bytes[i]] - cdfMin) / (bytes.length - cdfMin)) * 255);
  }
  return { equalized, histogram: hist };
}

// NBR #1394 — createDecodeResultDAG
// Directed acyclic graph with topological sort
function createDecodeResultDAG() {
  const nodes = new Map();
  const edges = [];
  return {
    addNode(id, data) { nodes.set(id, { data, outgoing: [], incoming: [] }); },
    addEdge(from, to) {
      if (!nodes.has(from) || !nodes.has(to)) return false;
      nodes.get(from).outgoing.push(to);
      nodes.get(to).incoming.push(from);
      edges.push({ from, to });
      return true;
    },
    topologicalSort() {
      const inDegree = new Map();
      for (const [id, node] of nodes) inDegree.set(id, node.incoming.length);
      const queue = [];
      for (const [id, deg] of inDegree) if (deg === 0) queue.push(id);
      const result = [];
      while (queue.length > 0) {
        const id = queue.shift();
        result.push(id);
        for (const out of nodes.get(id).outgoing) {
          inDegree.set(out, inDegree.get(out) - 1);
          if (inDegree.get(out) === 0) queue.push(out);
        }
      }
      return result;
    },
    nodeCount() { return nodes.size; },
    edgeCount() { return edges.length; }
  };
}

// NBR #1395 — computePayloadByteZeroCrossings
// Counts zero crossings (sign changes) in a centered byte sequence
function computePayloadByteZeroCrossings(bytes, opts) {
  if (!bytes || bytes.length < 2) return { crossings: 0, rate: 0 };
  const center = (opts && opts.center !== undefined) ? opts.center : 128;
  let crossings = 0;
  for (let i = 1; i < bytes.length; i++) {
    const prev = bytes[i - 1] - center;
    const curr = bytes[i] - center;
    if ((prev >= 0 && curr < 0) || (prev < 0 && curr >= 0)) crossings++;
  }
  return { crossings, rate: crossings / (bytes.length - 1) };
}

// NBR #1396 — createConfigDecodeThrottler
// Time-based throttler that limits execution frequency
function createConfigDecodeThrottler(opts) {
  const intervalMs = (opts && opts.intervalMs !== undefined) ? opts.intervalMs : 1000;
  let lastExec = 0;
  let blocked = 0;
  let allowed = 0;
  return {
    tryExecute() {
      const now = Date.now();
      if (now - lastExec >= intervalMs) {
        lastExec = now;
        allowed++;
        return true;
      }
      blocked++;
      return false;
    },
    getStats() { return { allowed, blocked, intervalMs }; },
    reset() { lastExec = 0; blocked = 0; allowed = 0; }
  };
}

// NBR #1397 — computePayloadByteBurstDetection
// Detects bursts of high-value bytes above a threshold
function computePayloadByteBurstDetection(bytes, opts) {
  if (!bytes || bytes.length === 0) return { bursts: [], count: 0, maxBurstLength: 0 };
  const threshold = (opts && opts.threshold !== undefined) ? opts.threshold : 200;
  const minLength = (opts && opts.minLength !== undefined) ? opts.minLength : 2;
  const bursts = [];
  let burstStart = -1;
  for (let i = 0; i <= bytes.length; i++) {
    const above = i < bytes.length && bytes[i] >= threshold;
    if (above && burstStart < 0) burstStart = i;
    if (!above && burstStart >= 0) {
      const len = i - burstStart;
      if (len >= minLength) bursts.push({ start: burstStart, end: i - 1, length: len });
      burstStart = -1;
    }
  }
  const maxLen = bursts.reduce((m, b) => Math.max(m, b.length), 0);
  return { bursts, count: bursts.length, maxBurstLength: maxLen };
}

// NBR #1398 — createDecodeResultSkipList
// Skip list for ordered key-value storage with O(log n) average operations
function createDecodeResultSkipList(opts) {
  const maxLevel = (opts && opts.maxLevel !== undefined) ? opts.maxLevel : 8;
  const head = { key: -Infinity, value: null, next: new Array(maxLevel).fill(null) };
  let size = 0;
  let level = 1;
  function randomLevel() {
    let l = 1;
    while (l < maxLevel && Math.random() < 0.5) l++;
    return l;
  }
  return {
    insert(key, value) {
      const update = new Array(maxLevel).fill(null);
      let curr = head;
      for (let i = level - 1; i >= 0; i--) {
        while (curr.next[i] && curr.next[i].key < key) curr = curr.next[i];
        update[i] = curr;
      }
      const newLevel = randomLevel();
      if (newLevel > level) {
        for (let i = level; i < newLevel; i++) update[i] = head;
        level = newLevel;
      }
      const node = { key, value, next: new Array(newLevel).fill(null) };
      for (let i = 0; i < newLevel; i++) {
        node.next[i] = update[i].next[i];
        update[i].next[i] = node;
      }
      size++;
    },
    find(key) {
      let curr = head;
      for (let i = level - 1; i >= 0; i--) {
        while (curr.next[i] && curr.next[i].key < key) curr = curr.next[i];
      }
      curr = curr.next[0];
      return (curr && curr.key === key) ? curr.value : undefined;
    },
    size() { return size; },
    toArray() {
      const arr = [];
      let curr = head.next[0];
      while (curr) { arr.push({ key: curr.key, value: curr.value }); curr = curr.next[0]; }
      return arr;
    }
  };
}

// NBR #1399 — computePayloadByteLocalVariance
// Computes local variance in sliding windows across byte array
function computePayloadByteLocalVariance(bytes, opts) {
  if (!bytes || bytes.length === 0) return { variances: [], meanVariance: 0 };
  const windowSize = (opts && opts.windowSize !== undefined) ? opts.windowSize : 5;
  const variances = [];
  for (let i = 0; i <= bytes.length - windowSize; i++) {
    let sum = 0, sum2 = 0;
    for (let j = i; j < i + windowSize; j++) {
      sum += bytes[j];
      sum2 += bytes[j] * bytes[j];
    }
    const mean = sum / windowSize;
    variances.push(sum2 / windowSize - mean * mean);
  }
  const meanVar = variances.length > 0 ? variances.reduce((a, b) => a + b, 0) / variances.length : 0;
  return { variances, meanVariance: meanVar };
}

// NBR #1400 — createConfigDecodeDebouncer
// Debouncer — only executes after quiet period with no new calls
function createConfigDecodeDebouncer(opts) {
  const delayMs = (opts && opts.delayMs !== undefined) ? opts.delayMs : 300;
  let timer = null;
  let callCount = 0;
  let execCount = 0;
  return {
    schedule(fn) {
      callCount++;
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => { execCount++; fn(); timer = null; }, delayMs);
    },
    cancel() { if (timer) { clearTimeout(timer); timer = null; } },
    isPending() { return timer !== null; },
    getStats() { return { callCount, execCount, delayMs }; }
  };
}

// NBR #1401 — computePayloadByteKurtosis
// Computes excess kurtosis of byte distribution
function computePayloadByteKurtosis(bytes, opts) {
  if (!bytes || bytes.length < 4) return { kurtosis: 0, skewness: 0, isHeavyTailed: false };
  const n = bytes.length;
  let sum = 0;
  for (let i = 0; i < n; i++) sum += bytes[i];
  const mean = sum / n;
  let m2 = 0, m3 = 0, m4 = 0;
  for (let i = 0; i < n; i++) {
    const d = bytes[i] - mean;
    const d2 = d * d;
    m2 += d2;
    m3 += d2 * d;
    m4 += d2 * d2;
  }
  m2 /= n; m3 /= n; m4 /= n;
  const sigma = Math.sqrt(m2);
  const skewness = sigma > 0 ? m3 / (sigma * sigma * sigma) : 0;
  const kurtosis = sigma > 0 ? (m4 / (m2 * m2)) - 3 : 0;
  return { kurtosis, skewness, isHeavyTailed: kurtosis > 1 };
}

// NBR #1402 — createDecodeResultSparseArray
// Sparse array implementation using Map for memory-efficient large index ranges
function createDecodeResultSparseArray() {
  const data = new Map();
  return {
    set(index, value) { data.set(index, value); },
    get(index) { return data.has(index) ? data.get(index) : undefined; },
    has(index) { return data.has(index); },
    delete(index) { return data.delete(index); },
    count() { return data.size; },
    indices() { return Array.from(data.keys()).sort((a, b) => a - b); },
    values() { return this.indices().map(i => data.get(i)); },
    forEach(fn) { for (const [k, v] of data) fn(v, k); }
  };
}

// NBR #1403 — computePayloadByteMoments
// Statistical moments (mean, variance, skew, kurtosis) in one pass
function computePayloadByteMoments(bytes, opts) {
  if (!bytes || bytes.length === 0) return { mean: 0, variance: 0, stdDev: 0, count: 0 };
  const n = bytes.length;
  let sum = 0, sum2 = 0, min = Infinity, max = -Infinity;
  for (let i = 0; i < n; i++) {
    sum += bytes[i];
    sum2 += bytes[i] * bytes[i];
    if (bytes[i] < min) min = bytes[i];
    if (bytes[i] > max) max = bytes[i];
  }
  const mean = sum / n;
  const variance = sum2 / n - mean * mean;
  return { mean, variance, stdDev: Math.sqrt(Math.max(0, variance)), min, max, count: n, range: max - min };
}

// NBR #1404 — createConfigDecodeCache
// TTL-based cache with automatic expiry
function createConfigDecodeCache(opts) {
  const ttlMs = (opts && opts.ttlMs !== undefined) ? opts.ttlMs : 60000;
  const maxSize = (opts && opts.maxSize !== undefined) ? opts.maxSize : 100;
  const store = new Map();
  function evict() {
    const now = Date.now();
    for (const [key, entry] of store) {
      if (now - entry.time > ttlMs) store.delete(key);
    }
  }
  return {
    set(key, value) {
      if (store.size >= maxSize) evict();
      store.set(key, { value, time: Date.now() });
    },
    get(key) {
      if (!store.has(key)) return undefined;
      const entry = store.get(key);
      if (Date.now() - entry.time > ttlMs) { store.delete(key); return undefined; }
      return entry.value;
    },
    has(key) { return this.get(key) !== undefined; },
    size() { evict(); return store.size; },
    clear() { store.clear(); }
  };
}

// NBR #1405 — computePayloadByteEdgeDetection
// 1D edge detection using first derivative magnitude
function computePayloadByteEdgeDetection(bytes, opts) {
  if (!bytes || bytes.length < 2) return { edges: [], count: 0, maxEdge: 0 };
  const threshold = (opts && opts.threshold !== undefined) ? opts.threshold : 30;
  const edges = [];
  let maxEdge = 0;
  for (let i = 1; i < bytes.length; i++) {
    const mag = Math.abs(bytes[i] - bytes[i - 1]);
    if (mag > maxEdge) maxEdge = mag;
    if (mag >= threshold) edges.push({ index: i, magnitude: mag });
  }
  return { edges, count: edges.length, maxEdge };
}

// NBR #1406 — createDecodeResultPriorityQueue
// Min-heap priority queue
function createDecodeResultPriorityQueue(opts) {
  const compareFn = (opts && opts.compare) || ((a, b) => a.priority - b.priority);
  const heap = [];
  function parent(i) { return Math.floor((i - 1) / 2); }
  function left(i) { return 2 * i + 1; }
  function right(i) { return 2 * i + 2; }
  function swap(i, j) { const t = heap[i]; heap[i] = heap[j]; heap[j] = t; }
  function siftUp(i) {
    while (i > 0 && compareFn(heap[i], heap[parent(i)]) < 0) { swap(i, parent(i)); i = parent(i); }
  }
  function siftDown(i) {
    const n = heap.length;
    while (true) {
      let min = i;
      const l = left(i), r = right(i);
      if (l < n && compareFn(heap[l], heap[min]) < 0) min = l;
      if (r < n && compareFn(heap[r], heap[min]) < 0) min = r;
      if (min === i) break;
      swap(i, min);
      i = min;
    }
  }
  return {
    push(item) { heap.push(item); siftUp(heap.length - 1); },
    pop() {
      if (heap.length === 0) return undefined;
      const top = heap[0];
      heap[0] = heap[heap.length - 1];
      heap.pop();
      if (heap.length > 0) siftDown(0);
      return top;
    },
    peek() { return heap.length > 0 ? heap[0] : undefined; },
    size() { return heap.length; },
    isEmpty() { return heap.length === 0; }
  };
}

// NBR #1407 — computePayloadByteHammingDistance
// Computes Hamming distance between two byte arrays (bitwise)
function computePayloadByteHammingDistance(bytes1, bytes2, opts) {
  if (!bytes1 || !bytes2) return { distance: 0, maxDistance: 0, similarity: 1 };
  const len = Math.min(bytes1.length, bytes2.length);
  if (len === 0) return { distance: 0, maxDistance: 0, similarity: 1 };
  let distance = 0;
  for (let i = 0; i < len; i++) {
    let xor = bytes1[i] ^ bytes2[i];
    while (xor) { distance += xor & 1; xor >>= 1; }
  }
  const maxDist = len * 8;
  return { distance, maxDistance: maxDist, similarity: 1 - distance / maxDist };
}

// NBR #1408 — createConfigDecodeRegistry
// Named component registry for decode pipeline modules
function createConfigDecodeRegistry() {
  const registry = new Map();
  return {
    register(name, component) {
      if (registry.has(name)) return false;
      registry.set(name, component);
      return true;
    },
    get(name) { return registry.get(name); },
    has(name) { return registry.has(name); },
    unregister(name) { return registry.delete(name); },
    list() { return Array.from(registry.keys()); },
    count() { return registry.size; },
    clear() { registry.clear(); }
  };
}

// NBR #1409 — computePayloadByteCRC32
// CRC-32 checksum computation for byte array
function computePayloadByteCRC32(bytes, opts) {
  if (!bytes || bytes.length === 0) return { crc: 0, hex: "00000000" };
  // Build CRC table
  const table = new Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    table[i] = c;
  }
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < bytes.length; i++) {
    crc = table[(crc ^ bytes[i]) & 0xFF] ^ (crc >>> 8);
  }
  crc = (crc ^ 0xFFFFFFFF) >>> 0;
  return { crc, hex: crc.toString(16).padStart(8, "0") };
}

// NBR #1410 — createDecodeResultUnionFind
// Union-Find (disjoint set) data structure
function createDecodeResultUnionFind(opts) {
  const parent = new Map();
  const rank = new Map();
  function find(x) {
    if (!parent.has(x)) { parent.set(x, x); rank.set(x, 0); }
    if (parent.get(x) !== x) parent.set(x, find(parent.get(x)));
    return parent.get(x);
  }
  return {
    makeSet(x) { if (!parent.has(x)) { parent.set(x, x); rank.set(x, 0); } },
    find(x) { return find(x); },
    union(x, y) {
      const rx = find(x), ry = find(y);
      if (rx === ry) return false;
      if (rank.get(rx) < rank.get(ry)) parent.set(rx, ry);
      else if (rank.get(rx) > rank.get(ry)) parent.set(ry, rx);
      else { parent.set(ry, rx); rank.set(rx, rank.get(rx) + 1); }
      return true;
    },
    connected(x, y) { return find(x) === find(y); },
    size() { return parent.size; }
  };
}

// NBR #1411 — computePayloadByteLevenshteinDistance
// Levenshtein edit distance between two byte sequences
function computePayloadByteLevenshteinDistance(bytes1, bytes2, opts) {
  if (!bytes1 || bytes1.length === 0) return { distance: bytes2 ? bytes2.length : 0 };
  if (!bytes2 || bytes2.length === 0) return { distance: bytes1.length };
  const m = bytes1.length, n = bytes2.length;
  const dp = new Array(m + 1);
  for (let i = 0; i <= m; i++) dp[i] = i;
  for (let j = 1; j <= n; j++) {
    let prev = dp[0];
    dp[0] = j;
    for (let i = 1; i <= m; i++) {
      const temp = dp[i];
      if (bytes1[i - 1] === bytes2[j - 1]) dp[i] = prev;
      else dp[i] = 1 + Math.min(prev, dp[i], dp[i - 1]);
      prev = temp;
    }
  }
  return { distance: dp[m], similarity: 1 - dp[m] / Math.max(m, n) };
}

// NBR #1412 — createConfigDecodeConnectionPool
// Pool of reusable connections with health checking
function createConfigDecodeConnectionPool(opts) {
  const maxConnections = (opts && opts.maxConnections !== undefined) ? opts.maxConnections : 5;
  const factory = (opts && opts.factory) || ((id) => ({ id, active: true }));
  const pool = [];
  let nextId = 0;
  return {
    acquire() {
      const available = pool.find(c => !c._inUse);
      if (available) { available._inUse = true; return available; }
      if (pool.length < maxConnections) {
        const conn = factory(nextId++);
        conn._inUse = true;
        pool.push(conn);
        return conn;
      }
      return null;
    },
    release(conn) { conn._inUse = false; },
    activeCount() { return pool.filter(c => c._inUse).length; },
    totalCount() { return pool.length; },
    availableCount() { return pool.filter(c => !c._inUse).length; }
  };
}

// NBR #1413 — computePayloadBytePermutationEntropy
// Permutation entropy for complexity analysis of byte sequences
function computePayloadBytePermutationEntropy(bytes, opts) {
  if (!bytes || bytes.length < 3) return { entropy: 0, maxEntropy: 0, normalized: 0 };
  const order = (opts && opts.order !== undefined) ? opts.order : 3;
  if (bytes.length < order) return { entropy: 0, maxEntropy: 0, normalized: 0 };
  const patterns = new Map();
  let total = 0;
  for (let i = 0; i <= bytes.length - order; i++) {
    const window = [];
    for (let j = 0; j < order; j++) window.push(bytes[i + j]);
    // Get ordinal pattern
    const indices = window.map((v, idx) => ({ v, idx })).sort((a, b) => a.v - b.v || a.idx - b.idx);
    const pattern = indices.map(x => x.idx).join(",");
    patterns.set(pattern, (patterns.get(pattern) || 0) + 1);
    total++;
  }
  let entropy = 0;
  for (const count of patterns.values()) {
    const p = count / total;
    if (p > 0) entropy -= p * Math.log2(p);
  }
  // Factorial of order
  let factorial = 1;
  for (let i = 2; i <= order; i++) factorial *= i;
  const maxEntropy = Math.log2(factorial);
  return { entropy, maxEntropy, normalized: maxEntropy > 0 ? entropy / maxEntropy : 0 };
}

// NBR #1414 — createDecodeResultRingBuffer
// Fixed-size ring buffer with wrap-around
function createDecodeResultRingBuffer(opts) {
  const capacity = (opts && opts.capacity !== undefined) ? opts.capacity : 16;
  const buffer = new Array(capacity);
  let head = 0, count = 0;
  return {
    push(item) {
      buffer[(head + count) % capacity] = item;
      if (count < capacity) count++;
      else head = (head + 1) % capacity;
    },
    get(index) {
      if (index < 0 || index >= count) return undefined;
      return buffer[(head + index) % capacity];
    },
    size() { return count; },
    capacity() { return capacity; },
    isFull() { return count === capacity; },
    toArray() {
      const arr = [];
      for (let i = 0; i < count; i++) arr.push(buffer[(head + i) % capacity]);
      return arr;
    },
    clear() { head = 0; count = 0; }
  };
}

// NBR #1415 — computePayloadByteCosineSimilarity
// Cosine similarity between two byte vectors
function computePayloadByteCosineSimilarity(bytes1, bytes2, opts) {
  if (!bytes1 || !bytes2 || bytes1.length === 0 || bytes2.length === 0) return { similarity: 0, distance: 1 };
  const len = Math.min(bytes1.length, bytes2.length);
  let dot = 0, mag1 = 0, mag2 = 0;
  for (let i = 0; i < len; i++) {
    dot += bytes1[i] * bytes2[i];
    mag1 += bytes1[i] * bytes1[i];
    mag2 += bytes2[i] * bytes2[i];
  }
  const denom = Math.sqrt(mag1) * Math.sqrt(mag2);
  const similarity = denom > 0 ? dot / denom : 0;
  return { similarity, distance: 1 - similarity };
}

// NBR #1416 — createConfigDecodeCommandQueue
// FIFO command queue with execute-all capability
function createConfigDecodeCommandQueue() {
  const queue = [];
  let executed = 0;
  return {
    enqueue(command) { queue.push(command); },
    executeNext() {
      if (queue.length === 0) return undefined;
      const cmd = queue.shift();
      executed++;
      return typeof cmd === "function" ? cmd() : cmd;
    },
    executeAll() {
      const results = [];
      while (queue.length > 0) results.push(this.executeNext());
      return results;
    },
    pending() { return queue.length; },
    executedCount() { return executed; },
    clear() { queue.length = 0; }
  };
}

// NBR #1417 — computePayloadByteJaccardIndex
// Jaccard index (intersection over union) of byte value sets
function computePayloadByteJaccardIndex(bytes1, bytes2, opts) {
  if (!bytes1 || !bytes2 || bytes1.length === 0 || bytes2.length === 0) return { index: 0, intersection: 0, union: 0 };
  const set1 = new Set(bytes1);
  const set2 = new Set(bytes2);
  let intersection = 0;
  for (const v of set1) if (set2.has(v)) intersection++;
  const union = set1.size + set2.size - intersection;
  return { index: union > 0 ? intersection / union : 0, intersection, union };
}

// NBR #1418 — createDecodeResultMatrix
// 2D matrix with basic operations
function createDecodeResultMatrix(opts) {
  const rows = (opts && opts.rows !== undefined) ? opts.rows : 3;
  const cols = (opts && opts.cols !== undefined) ? opts.cols : 3;
  const data = new Array(rows * cols).fill(0);
  return {
    get(r, c) { return data[r * cols + c]; },
    set(r, c, value) { data[r * cols + c] = value; },
    rows() { return rows; },
    cols() { return cols; },
    fill(value) { data.fill(value); },
    toArray() {
      const result = [];
      for (let r = 0; r < rows; r++) {
        const row = [];
        for (let c = 0; c < cols; c++) row.push(data[r * cols + c]);
        result.push(row);
      }
      return result;
    },
    trace() {
      let t = 0;
      const min = Math.min(rows, cols);
      for (let i = 0; i < min; i++) t += data[i * cols + i];
      return t;
    }
  };
}

// NBR #1419 — computePayloadByteQuantize
// Quantizes byte values to reduced number of levels
function computePayloadByteQuantize(bytes, opts) {
  if (!bytes || bytes.length === 0) return { quantized: [], levels: 0, error: 0 };
  const levels = (opts && opts.levels !== undefined) ? opts.levels : 16;
  const step = 256 / levels;
  const quantized = new Array(bytes.length);
  let totalError = 0;
  for (let i = 0; i < bytes.length; i++) {
    const q = Math.min(levels - 1, Math.floor(bytes[i] / step));
    const reconstructed = Math.round(q * step + step / 2);
    quantized[i] = Math.min(255, reconstructed);
    totalError += Math.abs(bytes[i] - quantized[i]);
  }
  return { quantized, levels, error: totalError / bytes.length };
}

// NBR #1420 — createConfigDecodeAbortController
// Abort controller for cancellable decode operations
function createConfigDecodeAbortController() {
  let aborted = false;
  let reason = null;
  const listeners = [];
  return {
    abort(r) { aborted = true; reason = r || "aborted"; for (const fn of listeners) fn(reason); },
    isAborted() { return aborted; },
    getReason() { return reason; },
    onAbort(fn) { listeners.push(fn); if (aborted) fn(reason); },
    throwIfAborted() { if (aborted) throw new Error(reason || "Operation aborted"); },
    reset() { aborted = false; reason = null; listeners.length = 0; }
  };
}

// NBR #1421 — computePayloadByteGradientMagnitude
// Computes gradient magnitude at each position using central differences
function computePayloadByteGradientMagnitude(bytes, opts) {
  if (!bytes || bytes.length < 3) return { magnitudes: [], maxGradient: 0, meanGradient: 0 };
  const magnitudes = new Array(bytes.length);
  magnitudes[0] = Math.abs(bytes[1] - bytes[0]);
  magnitudes[bytes.length - 1] = Math.abs(bytes[bytes.length - 1] - bytes[bytes.length - 2]);
  let maxG = 0, sumG = 0;
  for (let i = 1; i < bytes.length - 1; i++) {
    magnitudes[i] = Math.abs(bytes[i + 1] - bytes[i - 1]) / 2;
    if (magnitudes[i] > maxG) maxG = magnitudes[i];
    sumG += magnitudes[i];
  }
  return { magnitudes, maxGradient: maxG, meanGradient: sumG / (bytes.length - 2) };
}

// NBR #1422 — createDecodeResultHashMap
// Open-addressing hash map with linear probing
function createDecodeResultHashMap(opts) {
  const capacity = (opts && opts.capacity !== undefined) ? opts.capacity : 64;
  const keys = new Array(capacity).fill(null);
  const values = new Array(capacity).fill(null);
  let count = 0;
  function hash(key) {
    let h = 0;
    const s = String(key);
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) & (capacity - 1);
    return h;
  }
  return {
    set(key, value) {
      let idx = hash(key);
      for (let i = 0; i < capacity; i++) {
        const probe = (idx + i) % capacity;
        if (keys[probe] === null || keys[probe] === key) {
          if (keys[probe] === null) count++;
          keys[probe] = key;
          values[probe] = value;
          return true;
        }
      }
      return false; // full
    },
    get(key) {
      let idx = hash(key);
      for (let i = 0; i < capacity; i++) {
        const probe = (idx + i) % capacity;
        if (keys[probe] === null) return undefined;
        if (keys[probe] === key) return values[probe];
      }
      return undefined;
    },
    has(key) { return this.get(key) !== undefined; },
    size() { return count; },
    loadFactor() { return count / capacity; }
  };
}

// NBR #1423 — computePayloadByteSymbolPairFreq
// Computes frequency of consecutive byte pairs (digrams)
function computePayloadByteSymbolPairFreq(bytes, opts) {
  if (!bytes || bytes.length < 2) return { pairs: [], uniquePairs: 0, totalPairs: 0 };
  const counts = new Map();
  for (let i = 0; i < bytes.length - 1; i++) {
    const key = bytes[i] * 256 + bytes[i + 1];
    counts.set(key, (counts.get(key) || 0) + 1);
  }
  const total = bytes.length - 1;
  const pairs = [];
  for (const [key, count] of counts) {
    pairs.push({ first: Math.floor(key / 256), second: key % 256, count, probability: count / total });
  }
  pairs.sort((a, b) => b.count - a.count);
  return { pairs: pairs.slice(0, 20), uniquePairs: counts.size, totalPairs: total };
}

// NBR #1424 — createConfigDecodeHealthCheck
// Health check monitor with status tracking
function createConfigDecodeHealthCheck() {
  const checks = new Map();
  return {
    register(name, checkFn) { checks.set(name, { fn: checkFn, lastResult: null, lastRun: 0 }); },
    run(name) {
      if (!checks.has(name)) return { healthy: false, error: "unknown check" };
      const check = checks.get(name);
      try {
        const result = check.fn();
        check.lastResult = { healthy: true, ...result };
        check.lastRun = Date.now();
        return check.lastResult;
      } catch (e) {
        check.lastResult = { healthy: false, error: e.message };
        check.lastRun = Date.now();
        return check.lastResult;
      }
    },
    runAll() {
      const results = {};
      for (const name of checks.keys()) results[name] = this.run(name);
      return results;
    },
    isHealthy() {
      for (const check of checks.values()) {
        if (!check.lastResult || !check.lastResult.healthy) return false;
      }
      return checks.size > 0;
    },
    list() { return Array.from(checks.keys()); }
  };
}

// NBR #1425 — computePayloadByteShannonEntropy
// Shannon entropy in bits per byte
function computePayloadByteShannonEntropy(bytes, opts) {
  if (!bytes || bytes.length === 0) return { entropy: 0, maxEntropy: 8, ratio: 0 };
  const counts = new Array(256).fill(0);
  for (let i = 0; i < bytes.length; i++) counts[bytes[i]]++;
  let entropy = 0;
  for (let i = 0; i < 256; i++) {
    if (counts[i] > 0) {
      const p = counts[i] / bytes.length;
      entropy -= p * Math.log2(p);
    }
  }
  return { entropy, maxEntropy: 8, ratio: entropy / 8 };
}

// NBR #1426 — createDecodeResultDualKeyMap
// Map with composite two-part keys
function createDecodeResultDualKeyMap() {
  const store = new Map();
  function makeKey(k1, k2) { return k1 + "\0" + k2; }
  return {
    set(key1, key2, value) { store.set(makeKey(key1, key2), value); },
    get(key1, key2) { return store.get(makeKey(key1, key2)); },
    has(key1, key2) { return store.has(makeKey(key1, key2)); },
    delete(key1, key2) { return store.delete(makeKey(key1, key2)); },
    size() { return store.size; },
    clear() { store.clear(); },
    entries() {
      const result = [];
      for (const [k, v] of store) {
        const parts = k.split("\0");
        result.push({ key1: parts[0], key2: parts[1], value: v });
      }
      return result;
    }
  };
}

// NBR #1427 — computePayloadByteCluster
// K-means style 1D clustering of byte values
function computePayloadByteCluster(bytes, opts) {
  if (!bytes || bytes.length === 0) return { clusters: [], k: 0 };
  const k = (opts && opts.k !== undefined) ? opts.k : 3;
  const maxIter = (opts && opts.maxIter !== undefined) ? opts.maxIter : 20;
  // Initialize centroids evenly
  const centroids = [];
  for (let i = 0; i < k; i++) centroids.push((i + 0.5) * 256 / k);
  let assignments = new Array(bytes.length).fill(0);
  for (let iter = 0; iter < maxIter; iter++) {
    // Assign
    for (let i = 0; i < bytes.length; i++) {
      let best = 0, bestDist = Infinity;
      for (let c = 0; c < k; c++) {
        const d = Math.abs(bytes[i] - centroids[c]);
        if (d < bestDist) { bestDist = d; best = c; }
      }
      assignments[i] = best;
    }
    // Update centroids
    let changed = false;
    for (let c = 0; c < k; c++) {
      let sum = 0, cnt = 0;
      for (let i = 0; i < bytes.length; i++) {
        if (assignments[i] === c) { sum += bytes[i]; cnt++; }
      }
      if (cnt > 0) {
        const newCentroid = sum / cnt;
        if (Math.abs(newCentroid - centroids[c]) > 0.01) changed = true;
        centroids[c] = newCentroid;
      }
    }
    if (!changed) break;
  }
  const clusters = centroids.map((c, idx) => ({
    centroid: c,
    count: assignments.filter(a => a === idx).length
  }));
  return { clusters, k };
}

// NBR #1428 — createConfigDecodeLogger
// Structured logger with log levels
function createConfigDecodeLogger(opts) {
  const level = (opts && opts.level) || "info";
  const levels = { debug: 0, info: 1, warn: 2, error: 3 };
  const minLevel = levels[level] || 0;
  const entries = [];
  return {
    debug(msg, data) { if (minLevel <= 0) entries.push({ level: "debug", msg, data, time: Date.now() }); },
    info(msg, data) { if (minLevel <= 1) entries.push({ level: "info", msg, data, time: Date.now() }); },
    warn(msg, data) { if (minLevel <= 2) entries.push({ level: "warn", msg, data, time: Date.now() }); },
    error(msg, data) { if (minLevel <= 3) entries.push({ level: "error", msg, data, time: Date.now() }); },
    getEntries(filterLevel) {
      if (!filterLevel) return entries.slice();
      return entries.filter(e => e.level === filterLevel);
    },
    count() { return entries.length; },
    clear() { entries.length = 0; }
  };
}

// NBR #1429 — computePayloadByteAdaptiveThreshold
// Adaptive thresholding with local mean or Otsu method
function computePayloadByteAdaptiveThreshold(bytes, opts) {
  if (!bytes || bytes.length === 0) return { thresholded: [], threshold: 0 };
  const method = (opts && opts.method) || "otsu";
  let threshold;
  if (method === "mean") {
    let sum = 0;
    for (let i = 0; i < bytes.length; i++) sum += bytes[i];
    threshold = sum / bytes.length;
  } else {
    // Otsu's method
    const hist = new Array(256).fill(0);
    for (let i = 0; i < bytes.length; i++) hist[bytes[i]]++;
    let total = bytes.length;
    let sumAll = 0;
    for (let i = 0; i < 256; i++) sumAll += i * hist[i];
    let sumB = 0, wB = 0, maxVariance = 0;
    threshold = 0;
    for (let t = 0; t < 256; t++) {
      wB += hist[t];
      if (wB === 0) continue;
      const wF = total - wB;
      if (wF === 0) break;
      sumB += t * hist[t];
      const mB = sumB / wB;
      const mF = (sumAll - sumB) / wF;
      const variance = wB * wF * (mB - mF) * (mB - mF);
      if (variance > maxVariance) { maxVariance = variance; threshold = t; }
    }
  }
  const thresholded = bytes.map(b => b >= threshold ? 1 : 0);
  return { thresholded, threshold };
}

// NBR #1430 — createDecodeResultBiMap
// Bidirectional map — lookup by key or value
function createDecodeResultBiMap() {
  const forward = new Map();
  const reverse = new Map();
  return {
    set(key, value) {
      if (forward.has(key)) reverse.delete(forward.get(key));
      if (reverse.has(value)) forward.delete(reverse.get(value));
      forward.set(key, value);
      reverse.set(value, key);
    },
    getByKey(key) { return forward.get(key); },
    getByValue(value) { return reverse.get(value); },
    hasKey(key) { return forward.has(key); },
    hasValue(value) { return reverse.has(value); },
    deleteByKey(key) {
      if (forward.has(key)) { reverse.delete(forward.get(key)); forward.delete(key); }
    },
    size() { return forward.size; }
  };
}

// NBR #1431 — computePayloadByteNormalize
// Min-max normalization of byte array to [0, 255] range
function computePayloadByteNormalize(bytes, opts) {
  if (!bytes || bytes.length === 0) return { normalized: [], min: 0, max: 0 };
  let min = Infinity, max = -Infinity;
  for (let i = 0; i < bytes.length; i++) {
    if (bytes[i] < min) min = bytes[i];
    if (bytes[i] > max) max = bytes[i];
  }
  const range = max - min;
  const normalized = bytes.map(b => range > 0 ? Math.round(((b - min) / range) * 255) : 128);
  return { normalized, min, max };
}

// NBR #1432 — createConfigDecodeValidator
// Schema-based validation for decode config objects
function createConfigDecodeValidator() {
  const rules = new Map();
  return {
    addRule(field, validatorFn, message) {
      rules.set(field, { fn: validatorFn, message: message || `Invalid ${field}` });
    },
    validate(obj) {
      const errors = [];
      for (const [field, rule] of rules) {
        const value = obj && obj[field];
        if (!rule.fn(value)) errors.push({ field, message: rule.message });
      }
      return { valid: errors.length === 0, errors };
    },
    ruleCount() { return rules.size; },
    removeRule(field) { rules.delete(field); }
  };
}

// NBR #1433 — computePayloadByteWindowedFFT
// Simplified windowed FFT magnitude spectrum for byte data
function computePayloadByteWindowedFFT(bytes, opts) {
  if (!bytes || bytes.length < 4) return { magnitudes: [], dominantFreq: 0 };
  const n = bytes.length;
  // Apply Hann window and compute DFT magnitudes for first half
  const halfN = Math.floor(n / 2);
  const magnitudes = new Array(halfN);
  let maxMag = 0, maxIdx = 0;
  for (let k = 0; k < halfN; k++) {
    let re = 0, im = 0;
    for (let t = 0; t < n; t++) {
      const w = 0.5 * (1 - Math.cos(2 * Math.PI * t / (n - 1))); // Hann
      const angle = -2 * Math.PI * k * t / n;
      re += bytes[t] * w * Math.cos(angle);
      im += bytes[t] * w * Math.sin(angle);
    }
    magnitudes[k] = Math.sqrt(re * re + im * im);
    if (k > 0 && magnitudes[k] > maxMag) { maxMag = magnitudes[k]; maxIdx = k; }
  }
  return { magnitudes, dominantFreq: maxIdx };
}

// NBR #1434 — createDecodeResultCounter
// Thread-safe-style atomic counter with snapshot
function createDecodeResultCounter(opts) {
  const initial = (opts && opts.initial !== undefined) ? opts.initial : 0;
  let value = initial;
  let peak = initial;
  return {
    increment(n) { value += (n !== undefined ? n : 1); if (value > peak) peak = value; },
    decrement(n) { value -= (n !== undefined ? n : 1); },
    get() { return value; },
    getPeak() { return peak; },
    reset() { value = initial; peak = initial; },
    snapshot() { return { value, peak, initial }; }
  };
}

// NBR #1435 — computePayloadByteContrast
// Measures local contrast using RMS contrast metric
function computePayloadByteContrast(bytes, opts) {
  if (!bytes || bytes.length === 0) return { rmsContrast: 0, michelson: 0, weber: 0 };
  let sum = 0, min = Infinity, max = -Infinity;
  for (let i = 0; i < bytes.length; i++) {
    sum += bytes[i];
    if (bytes[i] < min) min = bytes[i];
    if (bytes[i] > max) max = bytes[i];
  }
  const mean = sum / bytes.length;
  let sumSq = 0;
  for (let i = 0; i < bytes.length; i++) sumSq += (bytes[i] - mean) * (bytes[i] - mean);
  const rmsContrast = Math.sqrt(sumSq / bytes.length) / 255;
  const michelson = (max + min) > 0 ? (max - min) / (max + min) : 0;
  const weber = mean > 0 ? (max - mean) / mean : 0;
  return { rmsContrast, michelson, weber };
}

// NBR #1436 — createConfigDecodeTaskRunner
// Sequential task runner with error handling
function createConfigDecodeTaskRunner() {
  const tasks = [];
  let completed = 0;
  let failed = 0;
  return {
    add(name, fn) { tasks.push({ name, fn, status: "pending", result: null, error: null }); },
    runAll() {
      const results = [];
      for (const task of tasks) {
        try {
          task.result = task.fn();
          task.status = "completed";
          completed++;
          results.push({ name: task.name, success: true, result: task.result });
        } catch (e) {
          task.status = "failed";
          task.error = e.message;
          failed++;
          results.push({ name: task.name, success: false, error: e.message });
        }
      }
      return results;
    },
    getStats() { return { total: tasks.length, completed, failed, pending: tasks.length - completed - failed }; },
    clear() { tasks.length = 0; completed = 0; failed = 0; }
  };
}

// NBR #1437 — computePayloadByteHilbertTransform
// Discrete Hilbert transform approximation for analytic signal
function computePayloadByteHilbertTransform(bytes, opts) {
  if (!bytes || bytes.length < 2) return { envelope: [], instantFreq: [] };
  const n = bytes.length;
  // Simple envelope estimation using analytic signal approximation
  const envelope = new Array(n);
  const instantFreq = new Array(n);
  for (let i = 0; i < n; i++) {
    // Compute Hilbert via finite differences approximation
    let hilbert = 0;
    for (let k = 1; k <= Math.min(16, Math.floor(n / 2)); k++) {
      const idx1 = (i + k) % n;
      const idx2 = (i - k + n) % n;
      if (k % 2 === 1) hilbert += (bytes[idx1] - bytes[idx2]) / (Math.PI * k);
    }
    envelope[i] = Math.sqrt(bytes[i] * bytes[i] + hilbert * hilbert);
    instantFreq[i] = i > 0 ? Math.abs(envelope[i] - envelope[i - 1]) : 0;
  }
  return { envelope, instantFreq };
}

// NBR #1438 — createDecodeResultTreeMap
// Sorted map using binary search (tree-like behavior)
function createDecodeResultTreeMap() {
  const keys = [];
  const values = [];
  function bsearch(key) {
    let lo = 0, hi = keys.length;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (keys[mid] < key) lo = mid + 1; else hi = mid;
    }
    return lo;
  }
  return {
    set(key, value) {
      const idx = bsearch(key);
      if (idx < keys.length && keys[idx] === key) { values[idx] = value; }
      else { keys.splice(idx, 0, key); values.splice(idx, 0, value); }
    },
    get(key) {
      const idx = bsearch(key);
      return (idx < keys.length && keys[idx] === key) ? values[idx] : undefined;
    },
    has(key) { const idx = bsearch(key); return idx < keys.length && keys[idx] === key; },
    min() { return keys.length > 0 ? { key: keys[0], value: values[0] } : undefined; },
    max() { return keys.length > 0 ? { key: keys[keys.length - 1], value: values[values.length - 1] } : undefined; },
    size() { return keys.length; },
    range(lo, hi) {
      const result = [];
      const start = bsearch(lo);
      for (let i = start; i < keys.length && keys[i] <= hi; i++) {
        result.push({ key: keys[i], value: values[i] });
      }
      return result;
    }
  };
}

// NBR #1439 — computePayloadByteCompressibility
// Estimates compressibility by comparing raw size to simple encoding sizes
function computePayloadByteCompressibility(bytes, opts) {
  if (!bytes || bytes.length === 0) return { ratio: 1, rleSize: 0, uniqueRatio: 0 };
  // RLE size estimate
  let rleSize = 0, i = 0;
  while (i < bytes.length) {
    let run = 1;
    while (i + run < bytes.length && bytes[i + run] === bytes[i] && run < 255) run++;
    rleSize += 2;
    i += run;
  }
  const uniqueBytes = new Set(bytes).size;
  return {
    ratio: rleSize / bytes.length,
    rleSize,
    uniqueRatio: uniqueBytes / 256,
    uniqueBytes,
    originalSize: bytes.length
  };
}

// NBR #1440 — createConfigDecodeEventBus
// Global event bus with wildcard support
function createConfigDecodeEventBus() {
  const handlers = new Map();
  let totalEmitted = 0;
  return {
    on(event, fn) {
      if (!handlers.has(event)) handlers.set(event, []);
      handlers.get(event).push(fn);
    },
    emit(event, data) {
      totalEmitted++;
      let count = 0;
      if (handlers.has(event)) {
        for (const fn of handlers.get(event)) { fn(data); count++; }
      }
      if (handlers.has("*")) {
        for (const fn of handlers.get("*")) { fn(event, data); count++; }
      }
      return count;
    },
    off(event, fn) {
      if (!handlers.has(event)) return;
      const arr = handlers.get(event);
      const idx = arr.indexOf(fn);
      if (idx >= 0) arr.splice(idx, 1);
    },
    totalEmitted() { return totalEmitted; },
    eventNames() { return Array.from(handlers.keys()); }
  };
}

// NBR #1441 — computePayloadByteMorphology
// 1D morphological operations (dilate/erode) on byte array
function computePayloadByteMorphology(bytes, opts) {
  if (!bytes || bytes.length === 0) return { result: [], operation: "" };
  const operation = (opts && opts.operation) || "dilate";
  const radius = (opts && opts.radius !== undefined) ? opts.radius : 1;
  const result = new Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) {
    let val = bytes[i];
    for (let j = -radius; j <= radius; j++) {
      const idx = i + j;
      if (idx >= 0 && idx < bytes.length) {
        if (operation === "dilate") val = Math.max(val, bytes[idx]);
        else val = Math.min(val, bytes[idx]);
      }
    }
    result[i] = val;
  }
  return { result, operation };
}

// NBR #1442 — createDecodeResultGraphAdjList
// Adjacency list graph with BFS and connected components
function createDecodeResultGraphAdjList() {
  const adj = new Map();
  return {
    addNode(id) { if (!adj.has(id)) adj.set(id, new Set()); },
    addEdge(from, to) {
      if (!adj.has(from)) adj.set(from, new Set());
      if (!adj.has(to)) adj.set(to, new Set());
      adj.get(from).add(to);
      adj.get(to).add(from);
    },
    neighbors(id) { return adj.has(id) ? Array.from(adj.get(id)) : []; },
    bfs(start) {
      const visited = new Set();
      const queue = [start];
      const order = [];
      visited.add(start);
      while (queue.length > 0) {
        const node = queue.shift();
        order.push(node);
        if (adj.has(node)) {
          for (const n of adj.get(node)) {
            if (!visited.has(n)) { visited.add(n); queue.push(n); }
          }
        }
      }
      return order;
    },
    nodeCount() { return adj.size; },
    edgeCount() {
      let count = 0;
      for (const edges of adj.values()) count += edges.size;
      return count / 2;
    }
  };
}

// NBR #1443 — computePayloadByteStandardize
// Z-score standardization of byte array (zero mean, unit variance)
function computePayloadByteStandardize(bytes, opts) {
  if (!bytes || bytes.length === 0) return { standardized: [], mean: 0, stdDev: 0 };
  let sum = 0;
  for (let i = 0; i < bytes.length; i++) sum += bytes[i];
  const mean = sum / bytes.length;
  let varSum = 0;
  for (let i = 0; i < bytes.length; i++) varSum += (bytes[i] - mean) * (bytes[i] - mean);
  const stdDev = Math.sqrt(varSum / bytes.length);
  const standardized = bytes.map(b => stdDev > 0 ? (b - mean) / stdDev : 0);
  return { standardized, mean, stdDev };
}

// NBR #1444 — createConfigDecodeSnapshot
// Immutable snapshot capture for decode config state
function createConfigDecodeSnapshot() {
  const snapshots = [];
  return {
    capture(state) {
      const snap = JSON.parse(JSON.stringify(state));
      snap._timestamp = Date.now();
      snap._id = snapshots.length;
      snapshots.push(snap);
      return snap._id;
    },
    restore(id) {
      if (id < 0 || id >= snapshots.length) return undefined;
      return JSON.parse(JSON.stringify(snapshots[id]));
    },
    latest() { return snapshots.length > 0 ? this.restore(snapshots.length - 1) : undefined; },
    count() { return snapshots.length; },
    diff(id1, id2) {
      const s1 = this.restore(id1);
      const s2 = this.restore(id2);
      if (!s1 || !s2) return [];
      const changes = [];
      const allKeys = new Set([...Object.keys(s1), ...Object.keys(s2)]);
      for (const k of allKeys) {
        if (k.startsWith("_")) continue;
        if (JSON.stringify(s1[k]) !== JSON.stringify(s2[k])) changes.push({ key: k, from: s1[k], to: s2[k] });
      }
      return changes;
    }
  };
}

// NBR #1445 — computePayloadByteTransitionMatrix
// Computes byte-to-byte transition probability matrix
function computePayloadByteTransitionMatrix(bytes, opts) {
  if (!bytes || bytes.length < 2) return { matrix: null, states: 0 };
  const bins = (opts && opts.bins !== undefined) ? opts.bins : 16;
  const binSize = 256 / bins;
  const matrix = Array.from({ length: bins }, () => new Array(bins).fill(0));
  const rowTotals = new Array(bins).fill(0);
  for (let i = 0; i < bytes.length - 1; i++) {
    const from = Math.min(bins - 1, Math.floor(bytes[i] / binSize));
    const to = Math.min(bins - 1, Math.floor(bytes[i + 1] / binSize));
    matrix[from][to]++;
    rowTotals[from]++;
  }
  // Normalize to probabilities
  for (let r = 0; r < bins; r++) {
    if (rowTotals[r] > 0) {
      for (let c = 0; c < bins; c++) matrix[r][c] /= rowTotals[r];
    }
  }
  return { matrix, states: bins };
}

// NBR #1446 — createDecodeResultObservable
// Observable value with change notification
function createDecodeResultObservable(opts) {
  let value = (opts && opts.initial !== undefined) ? opts.initial : null;
  const watchers = [];
  return {
    get() { return value; },
    set(newValue) {
      const oldValue = value;
      value = newValue;
      for (const fn of watchers) fn(newValue, oldValue);
    },
    watch(fn) {
      watchers.push(fn);
      return () => {
        const idx = watchers.indexOf(fn);
        if (idx >= 0) watchers.splice(idx, 1);
      };
    },
    watcherCount() { return watchers.length; }
  };
}

// NBR #1447 — computePayloadByteSlopeIntercept
// Linear regression (slope, intercept) of byte values vs index
function computePayloadByteSlopeIntercept(bytes, opts) {
  if (!bytes || bytes.length < 2) return { slope: 0, intercept: 0, r2: 0 };
  const n = bytes.length;
  let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0, sumY2 = 0;
  for (let i = 0; i < n; i++) {
    sumX += i;
    sumY += bytes[i];
    sumXY += i * bytes[i];
    sumX2 += i * i;
    sumY2 += bytes[i] * bytes[i];
  }
  const denom = n * sumX2 - sumX * sumX;
  if (denom === 0) return { slope: 0, intercept: sumY / n, r2: 0 };
  const slope = (n * sumXY - sumX * sumY) / denom;
  const intercept = (sumY - slope * sumX) / n;
  const ssTot = sumY2 - sumY * sumY / n;
  const ssRes = ssTot - slope * (sumXY - sumX * sumY / n);
  const r2 = ssTot > 0 ? 1 - ssRes / ssTot : 0;
  return { slope, intercept, r2: Math.max(0, Math.min(1, r2)) };
}

// NBR #1448 — createConfigDecodeAggregator
// Aggregates multiple decode results with configurable strategy
function createConfigDecodeAggregator(opts) {
  const strategy = (opts && opts.strategy) || "best";
  const results = [];
  return {
    add(result) { results.push(result); },
    aggregate() {
      if (results.length === 0) return null;
      if (strategy === "best") {
        return results.reduce((best, r) => (r.confidence || 0) > (best.confidence || 0) ? r : best, results[0]);
      }
      if (strategy === "latest") return results[results.length - 1];
      if (strategy === "first") return results[0];
      return results[0];
    },
    count() { return results.length; },
    getAll() { return results.slice(); },
    clear() { results.length = 0; }
  };
}

// NBR #1449 — computePayloadByteSymmetry
// Measures byte array symmetry (palindrome-likeness)
function computePayloadByteSymmetry(bytes, opts) {
  if (!bytes || bytes.length === 0) return { score: 0, mismatches: 0 };
  const half = Math.floor(bytes.length / 2);
  let matches = 0, mismatches = 0;
  for (let i = 0; i < half; i++) {
    if (bytes[i] === bytes[bytes.length - 1 - i]) matches++;
    else mismatches++;
  }
  return { score: half > 0 ? matches / half : 1, mismatches, totalCompared: half };
}

// NBR #1450 — createDecodeResultLazyMap
// Map with lazy-evaluated values (computed on first access)
function createDecodeResultLazyMap() {
  const factories = new Map();
  const cache = new Map();
  return {
    define(key, factory) { factories.set(key, factory); cache.delete(key); },
    get(key) {
      if (cache.has(key)) return cache.get(key);
      if (factories.has(key)) {
        const value = factories.get(key)();
        cache.set(key, value);
        return value;
      }
      return undefined;
    },
    isComputed(key) { return cache.has(key); },
    invalidate(key) { cache.delete(key); },
    keys() { return Array.from(factories.keys()); },
    computedCount() { return cache.size; }
  };
}

// NBR #1451 — computePayloadByteResample
// Resamples byte array to target length using linear interpolation
function computePayloadByteResample(bytes, opts) {
  if (!bytes || bytes.length === 0) return { resampled: [], targetLength: 0 };
  const targetLength = (opts && opts.targetLength !== undefined) ? opts.targetLength : bytes.length;
  if (targetLength <= 0) return { resampled: [], targetLength: 0 };
  if (targetLength === bytes.length) return { resampled: Array.from(bytes), targetLength };
  const resampled = new Array(targetLength);
  const ratio = (bytes.length - 1) / (targetLength - 1 || 1);
  for (let i = 0; i < targetLength; i++) {
    const srcPos = i * ratio;
    const lo = Math.floor(srcPos);
    const hi = Math.min(lo + 1, bytes.length - 1);
    const frac = srcPos - lo;
    resampled[i] = Math.round(bytes[lo] * (1 - frac) + bytes[hi] * frac);
  }
  return { resampled, targetLength };
}

// NBR #1452 — createConfigDecodeComposite
// Composites multiple decode configs into a merged config
function createConfigDecodeComposite() {
  const layers = [];
  return {
    addLayer(config, priority) {
      layers.push({ config, priority: priority !== undefined ? priority : layers.length });
      layers.sort((a, b) => b.priority - a.priority); // higher priority first
    },
    resolve(key) {
      for (const layer of layers) {
        if (layer.config && layer.config[key] !== undefined) return layer.config[key];
      }
      return undefined;
    },
    resolveAll() {
      const merged = {};
      // Lower priority first so higher priority overwrites
      for (let i = layers.length - 1; i >= 0; i--) {
        if (layers[i].config) Object.assign(merged, layers[i].config);
      }
      return merged;
    },
    layerCount() { return layers.length; },
    clear() { layers.length = 0; }
  };
}

// NBR #1453 — computePayloadByteTrendline
// Computes linear trendline and residuals
function computePayloadByteTrendline(bytes, opts) {
  if (!bytes || bytes.length < 2) return { trend: [], residuals: [], direction: "flat" };
  const n = bytes.length;
  let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
  for (let i = 0; i < n; i++) {
    sumX += i; sumY += bytes[i]; sumXY += i * bytes[i]; sumX2 += i * i;
  }
  const denom = n * sumX2 - sumX * sumX;
  const slope = denom !== 0 ? (n * sumXY - sumX * sumY) / denom : 0;
  const intercept = (sumY - slope * sumX) / n;
  const trend = new Array(n);
  const residuals = new Array(n);
  for (let i = 0; i < n; i++) {
    trend[i] = slope * i + intercept;
    residuals[i] = bytes[i] - trend[i];
  }
  const direction = slope > 1 ? "rising" : slope < -1 ? "falling" : "flat";
  return { trend, residuals, direction, slope };
}

// NBR #1454 — createDecodeResultIndexedCollection
// Collection with multiple indexed fields for fast lookup
function createDecodeResultIndexedCollection() {
  const items = [];
  const indices = new Map();
  return {
    createIndex(field) { indices.set(field, new Map()); },
    add(item) {
      const id = items.length;
      items.push(item);
      for (const [field, idx] of indices) {
        const val = item[field];
        if (val !== undefined) {
          if (!idx.has(val)) idx.set(val, []);
          idx.get(val).push(id);
        }
      }
      return id;
    },
    findBy(field, value) {
      const idx = indices.get(field);
      if (!idx || !idx.has(value)) return [];
      return idx.get(value).map(id => items[id]);
    },
    getById(id) { return items[id]; },
    count() { return items.length; },
    all() { return items.slice(); }
  };
}

// NBR #1455 — computePayloadByteDerivative
// Nth-order finite difference derivative of byte array
function computePayloadByteDerivative(bytes, opts) {
  if (!bytes || bytes.length < 2) return { derivative: [], order: 0 };
  const order = (opts && opts.order !== undefined) ? opts.order : 1;
  let current = Array.from(bytes);
  for (let o = 0; o < order; o++) {
    if (current.length < 2) break;
    const next = new Array(current.length - 1);
    for (let i = 0; i < current.length - 1; i++) next[i] = current[i + 1] - current[i];
    current = next;
  }
  return { derivative: current, order };
}

// NBR #1456 — createConfigDecodeBuilder
// Fluent builder pattern for constructing decode configs
function createConfigDecodeBuilder() {
  const config = {};
  const builder = {
    set(key, value) { config[key] = value; return builder; },
    setIfAbsent(key, value) { if (config[key] === undefined) config[key] = value; return builder; },
    merge(obj) { Object.assign(config, obj); return builder; },
    build() { return Object.assign({}, config); },
    has(key) { return config[key] !== undefined; },
    keys() { return Object.keys(config); },
    reset() { for (const k of Object.keys(config)) delete config[k]; return builder; }
  };
  return builder;
}

// NBR #1457 — computePayloadByteWhitening
// Spectral whitening — decorrelation by normalizing differences
function computePayloadByteWhitening(bytes, opts) {
  if (!bytes || bytes.length < 2) return { whitened: [], gain: 0 };
  // Compute mean and subtract
  let sum = 0;
  for (let i = 0; i < bytes.length; i++) sum += bytes[i];
  const mean = sum / bytes.length;
  const centered = bytes.map(b => b - mean);
  // Compute RMS
  let rms = 0;
  for (let i = 0; i < centered.length; i++) rms += centered[i] * centered[i];
  rms = Math.sqrt(rms / centered.length);
  const gain = rms > 0 ? 1 / rms : 0;
  const whitened = centered.map(v => v * gain);
  return { whitened, gain, rms };
}

// NBR #1458 — createDecodeResultDisjointSet
// Disjoint set with weighted union and path compression
function createDecodeResultDisjointSet() {
  const parent = new Map();
  const size = new Map();
  let componentCount = 0;
  function find(x) {
    if (!parent.has(x)) { parent.set(x, x); size.set(x, 1); componentCount++; }
    if (parent.get(x) !== x) parent.set(x, find(parent.get(x)));
    return parent.get(x);
  }
  return {
    makeSet(x) { if (!parent.has(x)) { parent.set(x, x); size.set(x, 1); componentCount++; } },
    find(x) { return find(x); },
    union(x, y) {
      const rx = find(x), ry = find(y);
      if (rx === ry) return false;
      if (size.get(rx) < size.get(ry)) { parent.set(rx, ry); size.set(ry, size.get(ry) + size.get(rx)); }
      else { parent.set(ry, rx); size.set(rx, size.get(rx) + size.get(ry)); }
      componentCount--;
      return true;
    },
    connected(x, y) { return find(x) === find(y); },
    componentSize(x) { return size.get(find(x)) || 0; },
    components() { return componentCount; },
    totalElements() { return parent.size; }
  };
}

// NBR #1459 — computePayloadByteIntegral
// Cumulative sum (integral) of byte array
function computePayloadByteIntegral(bytes, opts) {
  if (!bytes || bytes.length === 0) return { integral: [], total: 0 };
  const integral = new Array(bytes.length);
  integral[0] = bytes[0];
  for (let i = 1; i < bytes.length; i++) integral[i] = integral[i - 1] + bytes[i];
  return { integral, total: integral[bytes.length - 1] };
}

// NBR #1460 — createConfigDecodePolicy
// Policy engine for decode decisions based on rules
function createConfigDecodePolicy() {
  const policies = [];
  return {
    addPolicy(name, condition, action) {
      policies.push({ name, condition, action });
    },
    evaluate(context) {
      const results = [];
      for (const p of policies) {
        if (p.condition(context)) results.push({ name: p.name, action: p.action(context) });
      }
      return results;
    },
    firstMatch(context) {
      for (const p of policies) {
        if (p.condition(context)) return { name: p.name, action: p.action(context) };
      }
      return null;
    },
    count() { return policies.length; },
    clear() { policies.length = 0; }
  };
}

// NBR #1461 — computePayloadBytePatternMatch
// Simple pattern matching in byte arrays with wildcards
function computePayloadBytePatternMatch(bytes, opts) {
  if (!bytes || bytes.length === 0 || !opts || !opts.pattern) return { matches: [], count: 0 };
  const pattern = opts.pattern;
  const wildcard = opts.wildcard !== undefined ? opts.wildcard : -1;
  const matches = [];
  for (let i = 0; i <= bytes.length - pattern.length; i++) {
    let match = true;
    for (let j = 0; j < pattern.length; j++) {
      if (pattern[j] !== wildcard && bytes[i + j] !== pattern[j]) { match = false; break; }
    }
    if (match) matches.push(i);
  }
  return { matches, count: matches.length };
}

// NBR #1462 — createDecodeResultCircularBuffer
// Circular buffer with overwrite-oldest semantics
function createDecodeResultCircularBuffer(opts) {
  const capacity = (opts && opts.capacity !== undefined) ? opts.capacity : 32;
  const buffer = new Array(capacity);
  let writeIdx = 0, count = 0;
  return {
    write(value) {
      buffer[writeIdx] = value;
      writeIdx = (writeIdx + 1) % capacity;
      if (count < capacity) count++;
    },
    read(offset) {
      if (offset >= count) return undefined;
      const readIdx = (writeIdx - count + offset + capacity) % capacity;
      return buffer[readIdx];
    },
    latest() { return count > 0 ? buffer[(writeIdx - 1 + capacity) % capacity] : undefined; },
    oldest() { return count > 0 ? buffer[(writeIdx - count + capacity) % capacity] : undefined; },
    size() { return count; },
    capacity() { return capacity; },
    toArray() {
      const arr = [];
      for (let i = 0; i < count; i++) arr.push(this.read(i));
      return arr;
    }
  };
}

// NBR #1463 — computePayloadByteBitwiseEntropy
// Entropy computed per-bit across all byte positions
function computePayloadByteBitwiseEntropy(bytes, opts) {
  if (!bytes || bytes.length === 0) return { bitEntropies: [], meanEntropy: 0 };
  const bitEntropies = new Array(8);
  for (let bit = 0; bit < 8; bit++) {
    let ones = 0;
    for (let i = 0; i < bytes.length; i++) {
      if (bytes[i] & (1 << bit)) ones++;
    }
    const p1 = ones / bytes.length;
    const p0 = 1 - p1;
    bitEntropies[bit] = (p0 > 0 && p1 > 0) ? -(p0 * Math.log2(p0) + p1 * Math.log2(p1)) : 0;
  }
  const meanEntropy = bitEntropies.reduce((a, b) => a + b, 0) / 8;
  return { bitEntropies, meanEntropy };
}

// NBR #1464 — createConfigDecodeDispatcher
// Action dispatcher with registered handlers
function createConfigDecodeDispatcher() {
  const handlers = new Map();
  let dispatched = 0;
  return {
    register(action, handler) { handlers.set(action, handler); },
    dispatch(action, payload) {
      dispatched++;
      if (handlers.has(action)) return handlers.get(action)(payload);
      return undefined;
    },
    hasHandler(action) { return handlers.has(action); },
    unregister(action) { handlers.delete(action); },
    dispatchCount() { return dispatched; },
    actions() { return Array.from(handlers.keys()); }
  };
}

// NBR #1465 — computePayloadByteSmooth
// Gaussian-like smoothing using repeated box filter passes
function computePayloadByteSmooth(bytes, opts) {
  if (!bytes || bytes.length < 3) return { smoothed: bytes ? Array.from(bytes) : [], passes: 0 };
  const passes = (opts && opts.passes !== undefined) ? opts.passes : 2;
  let current = Array.from(bytes);
  for (let p = 0; p < passes; p++) {
    const next = new Array(current.length);
    next[0] = (current[0] + current[1]) / 2;
    next[current.length - 1] = (current[current.length - 2] + current[current.length - 1]) / 2;
    for (let i = 1; i < current.length - 1; i++) {
      next[i] = (current[i - 1] + current[i] + current[i + 1]) / 3;
    }
    current = next;
  }
  return { smoothed: current, passes };
}

// NBR #1466 — createDecodeResultMultiMap
// Map allowing multiple values per key
function createDecodeResultMultiMap() {
  const store = new Map();
  let totalValues = 0;
  return {
    add(key, value) {
      if (!store.has(key)) store.set(key, []);
      store.get(key).push(value);
      totalValues++;
    },
    get(key) { return store.has(key) ? store.get(key).slice() : []; },
    has(key) { return store.has(key); },
    removeAll(key) {
      if (store.has(key)) { totalValues -= store.get(key).length; store.delete(key); }
    },
    keyCount() { return store.size; },
    totalCount() { return totalValues; },
    keys() { return Array.from(store.keys()); }
  };
}

// --- NBR #1467: computePayloadByteRunLengthEncode ---
function computePayloadByteRunLengthEncode(bytes, opts) {
  if (!bytes || bytes.length === 0) return { runs: [], totalRuns: 0, compressionRatio: 0 };
  const o = Object.assign({ minRun: 1 }, opts || {});
  const runs = [];
  let i = 0;
  while (i < bytes.length) {
    const val = bytes[i];
    let count = 1;
    while (i + count < bytes.length && bytes[i + count] === val) count++;
    if (count >= o.minRun) {
      runs.push({ value: val, count: count });
    } else {
      for (let j = 0; j < count; j++) runs.push({ value: val, count: 1 });
    }
    i += count;
  }
  return { runs: runs, totalRuns: runs.length, compressionRatio: bytes.length / Math.max(1, runs.length) };
}

// --- NBR #1468: createConfigDecodeValidator ---
function createConfigDecodeValidator(opts) {
  const o = Object.assign({ strict: false }, opts || {});
  const rules = [];
  return {
    addRule(name, fn) { rules.push({ name: name, fn: fn }); },
    validate(config) {
      const errors = [];
      for (let i = 0; i < rules.length; i++) {
        try {
          const ok = rules[i].fn(config);
          if (!ok) errors.push({ rule: rules[i].name, message: "validation failed" });
        } catch (e) {
          errors.push({ rule: rules[i].name, message: e.message });
        }
      }
      return { valid: errors.length === 0, errors: errors, strict: o.strict, rulesChecked: rules.length };
    },
    ruleCount() { return rules.length; }
  };
}

// --- NBR #1469: computePayloadByteCrossCorrelation ---
function computePayloadByteCrossCorrelation(a, b, opts) {
  if (!a || !b || a.length === 0 || b.length === 0) return { correlation: [], peak: 0, peakLag: 0 };
  const o = Object.assign({ maxLag: Math.min(a.length, b.length) - 1, normalize: false }, opts || {});
  const maxLag = Math.min(o.maxLag, Math.min(a.length, b.length) - 1);
  const meanA = a.reduce((s, v) => s + v, 0) / a.length;
  const meanB = b.reduce((s, v) => s + v, 0) / b.length;
  const correlation = [];
  let peak = -Infinity;
  let peakLag = 0;
  for (let lag = 0; lag <= maxLag; lag++) {
    let sum = 0;
    let count = 0;
    for (let i = 0; i < a.length - lag; i++) {
      sum += (a[i] - meanA) * (b[i + lag] - meanB);
      count++;
    }
    const val = count > 0 ? sum / count : 0;
    correlation.push(val);
    if (val > peak) { peak = val; peakLag = lag; }
  }
  if (o.normalize && correlation.length > 0 && peak !== 0) {
    const scale = Math.abs(peak);
    for (let i = 0; i < correlation.length; i++) correlation[i] /= scale;
    peak = peak / scale;
  }
  return { correlation: correlation, peak: peak, peakLag: peakLag };
}

// --- NBR #1470: createDecodeResultTimeSeries ---
function createDecodeResultTimeSeries(opts) {
  const o = Object.assign({ maxPoints: 10000 }, opts || {});
  const points = [];
  return {
    add(timestamp, value) {
      if (points.length >= o.maxPoints) points.shift();
      points.push({ t: timestamp, v: value });
    },
    range(start, end) {
      return points.filter(p => p.t >= start && p.t <= end);
    },
    latest(n) {
      const count = Math.min(n || 1, points.length);
      return points.slice(points.length - count);
    },
    count() { return points.length; },
    average() {
      if (points.length === 0) return 0;
      return points.reduce((s, p) => s + p.v, 0) / points.length;
    }
  };
}

// --- NBR #1471: computePayloadByteZeroCrossings ---
function computePayloadByteZeroCrossings(bytes, opts) {
  if (!bytes || bytes.length < 2) return { crossings: [], count: 0, rate: 0 };
  const o = Object.assign({ baseline: 128 }, opts || {});
  const bl = o.baseline;
  const crossings = [];
  for (let i = 1; i < bytes.length; i++) {
    const prev = bytes[i - 1] - bl;
    const curr = bytes[i] - bl;
    if ((prev < 0 && curr >= 0) || (prev >= 0 && curr < 0)) {
      crossings.push(i);
    }
  }
  return { crossings: crossings, count: crossings.length, rate: crossings.length / (bytes.length - 1) };
}

// --- NBR #1472: createConfigDecodeTemplate ---
function createConfigDecodeTemplate(name, defaults, opts) {
  const o = Object.assign({}, opts || {});
  const base = Object.assign({}, defaults || {});
  return {
    name: name || "unnamed",
    instantiate(overrides) {
      return Object.assign({}, base, overrides || {});
    },
    getDefaults() { return Object.assign({}, base); },
    merge(other) {
      const merged = Object.assign({}, base);
      const otherDefaults = other.getDefaults ? other.getDefaults() : {};
      Object.keys(otherDefaults).forEach(k => {
        if (merged[k] === undefined) merged[k] = otherDefaults[k];
      });
      return createConfigDecodeTemplate(name + "+" + (other.name || ""), merged);
    }
  };
}

// --- NBR #1473: computePayloadBytePeakDetection ---
function computePayloadBytePeakDetection(bytes, opts) {
  if (!bytes || bytes.length < 3) return { peaks: [], valleys: [], peakCount: 0, valleyCount: 0 };
  const o = Object.assign({ minProminence: 0, minDistance: 1 }, opts || {});
  const rawPeaks = [];
  const rawValleys = [];
  for (let i = 1; i < bytes.length - 1; i++) {
    if (bytes[i] > bytes[i - 1] && bytes[i] > bytes[i + 1]) {
      const prom = Math.min(bytes[i] - bytes[i - 1], bytes[i] - bytes[i + 1]);
      if (prom >= o.minProminence) rawPeaks.push({ index: i, value: bytes[i], prominence: prom });
    }
    if (bytes[i] < bytes[i - 1] && bytes[i] < bytes[i + 1]) {
      const prom = Math.min(bytes[i - 1] - bytes[i], bytes[i + 1] - bytes[i]);
      if (prom >= o.minProminence) rawValleys.push({ index: i, value: bytes[i], prominence: prom });
    }
  }
  // Apply minimum distance filtering
  function filterDist(arr) {
    if (o.minDistance <= 1) return arr;
    const res = [];
    for (let i = 0; i < arr.length; i++) {
      if (res.length === 0 || arr[i].index - res[res.length - 1].index >= o.minDistance) {
        res.push(arr[i]);
      } else if (arr[i].prominence > res[res.length - 1].prominence) {
        res[res.length - 1] = arr[i];
      }
    }
    return res;
  }
  const peaks = filterDist(rawPeaks);
  const valleys = filterDist(rawValleys);
  return { peaks: peaks, valleys: valleys, peakCount: peaks.length, valleyCount: valleys.length };
}

// --- NBR #1474: createDecodeResultAggregator ---
function createDecodeResultAggregator(opts) {
  const o = Object.assign({ windowSize: 10 }, opts || {});
  const values = [];
  return {
    push(val) { values.push(val); },
    mean() {
      const w = values.slice(-o.windowSize);
      return w.length === 0 ? 0 : w.reduce((s, v) => s + v, 0) / w.length;
    },
    min() {
      const w = values.slice(-o.windowSize);
      return w.length === 0 ? 0 : Math.min.apply(null, w);
    },
    max() {
      const w = values.slice(-o.windowSize);
      return w.length === 0 ? 0 : Math.max.apply(null, w);
    },
    stddev() {
      const w = values.slice(-o.windowSize);
      if (w.length === 0) return 0;
      const m = w.reduce((s, v) => s + v, 0) / w.length;
      const variance = w.reduce((s, v) => s + (v - m) * (v - m), 0) / w.length;
      return Math.sqrt(variance);
    },
    count() { return values.length; },
    windowCount() { return Math.min(values.length, o.windowSize); }
  };
}

// --- NBR #1475: computePayloadByteGradient ---
function computePayloadByteGradient(bytes, opts) {
  if (!bytes || bytes.length < 2) return { gradient: [], maxGrad: 0, minGrad: 0, avgGrad: 0 };
  const o = Object.assign({ step: 1 }, opts || {});
  const step = Math.max(1, o.step);
  const gradient = [];
  for (let i = 0; i < bytes.length; i++) {
    let grad;
    if (i < step) {
      grad = (bytes[Math.min(i + step, bytes.length - 1)] - bytes[i]) / step;
    } else if (i >= bytes.length - step) {
      grad = (bytes[i] - bytes[Math.max(i - step, 0)]) / step;
    } else {
      grad = (bytes[i + step] - bytes[i - step]) / (2 * step);
    }
    gradient.push(grad);
  }
  const maxGrad = Math.max.apply(null, gradient);
  const minGrad = Math.min.apply(null, gradient);
  const avgGrad = gradient.reduce((s, v) => s + v, 0) / gradient.length;
  return { gradient: gradient, maxGrad: maxGrad, minGrad: minGrad, avgGrad: avgGrad };
}

// --- NBR #1476: createConfigDecodeConstraint ---
function createConfigDecodeConstraint(opts) {
  const o = Object.assign({}, opts || {});
  const constraints = [];
  return {
    addRange(key, min, max) { constraints.push({ type: "range", key: key, min: min, max: max }); },
    addEnum(key, values) { constraints.push({ type: "enum", key: key, values: values.slice() }); },
    addCustom(key, fn) { constraints.push({ type: "custom", key: key, fn: fn }); },
    check(config) {
      const violations = [];
      for (let i = 0; i < constraints.length; i++) {
        const c = constraints[i];
        const val = config[c.key];
        if (c.type === "range") {
          if (val < c.min || val > c.max) violations.push({ key: c.key, type: c.type, message: val + " not in [" + c.min + "," + c.max + "]" });
        } else if (c.type === "enum") {
          if (c.values.indexOf(val) < 0) violations.push({ key: c.key, type: c.type, message: val + " not in enum" });
        } else if (c.type === "custom") {
          if (!c.fn(val)) violations.push({ key: c.key, type: c.type, message: "custom check failed" });
        }
      }
      return { valid: violations.length === 0, violations: violations };
    },
    count() { return constraints.length; }
  };
}

// --- NBR #1477: computePayloadByteMoments ---
function computePayloadByteMoments(bytes, opts) {
  if (!bytes || bytes.length === 0) return { mean: 0, variance: 0, skewness: 0, kurtosis: 0 };
  const n = bytes.length;
  const mean = bytes.reduce((s, v) => s + v, 0) / n;
  let m2 = 0, m3 = 0, m4 = 0;
  for (let i = 0; i < n; i++) {
    const d = bytes[i] - mean;
    m2 += d * d;
    m3 += d * d * d;
    m4 += d * d * d * d;
  }
  m2 /= n; m3 /= n; m4 /= n;
  const stddev = Math.sqrt(m2);
  const skewness = stddev > 0 ? m3 / (stddev * stddev * stddev) : 0;
  const kurtosis = stddev > 0 ? m4 / (m2 * m2) - 3 : 0;
  return { mean: mean, variance: m2, skewness: skewness, kurtosis: kurtosis, stddev: stddev };
}

// --- NBR #1478: createDecodeResultSlidingWindow ---
function createDecodeResultSlidingWindow(size, opts) {
  const windowSize = size || 10;
  const o = Object.assign({}, opts || {});
  const buffer = [];
  return {
    push(val) {
      buffer.push(val);
      if (buffer.length > windowSize) buffer.shift();
    },
    full() { return buffer.length >= windowSize; },
    values() { return buffer.slice(); },
    sum() { return buffer.reduce((s, v) => s + v, 0); },
    mean() { return buffer.length === 0 ? 0 : buffer.reduce((s, v) => s + v, 0) / buffer.length; },
    count() { return buffer.length; },
    capacity() { return windowSize; }
  };
}

// --- NBR #1479: computePayloadByteAutoCorrelation ---
function computePayloadByteAutoCorrelation(bytes, opts) {
  if (!bytes || bytes.length < 2) return { acf: [], dominantPeriod: 0 };
  const o = Object.assign({ maxLag: Math.min(bytes.length - 1, 64) }, opts || {});
  const n = bytes.length;
  const mean = bytes.reduce((s, v) => s + v, 0) / n;
  let c0 = 0;
  for (let i = 0; i < n; i++) c0 += (bytes[i] - mean) * (bytes[i] - mean);
  if (c0 === 0) return { acf: new Array(o.maxLag + 1).fill(1), dominantPeriod: 0 };
  const acf = [];
  let bestLag = 0, bestVal = -Infinity;
  for (let lag = 0; lag <= o.maxLag; lag++) {
    let sum = 0;
    for (let i = 0; i < n - lag; i++) sum += (bytes[i] - mean) * (bytes[i + lag] - mean);
    const val = sum / c0;
    acf.push(val);
    if (lag > 0 && val > bestVal) { bestVal = val; bestLag = lag; }
  }
  return { acf: acf, dominantPeriod: bestLag };
}

// --- NBR #1480: createConfigDecodeProfiler ---
function createConfigDecodeProfiler(opts) {
  const o = Object.assign({}, opts || {});
  const timings = new Map();
  return {
    start(label) {
      timings.set(label, { start: Date.now(), end: 0, elapsed: 0 });
    },
    stop(label) {
      const t = timings.get(label);
      if (t) { t.end = Date.now(); t.elapsed = t.end - t.start; }
    },
    elapsed(label) {
      const t = timings.get(label);
      return t ? t.elapsed : 0;
    },
    report() {
      const r = {};
      timings.forEach((v, k) => { r[k] = v.elapsed; });
      return r;
    },
    labelCount() { return timings.size; }
  };
}

// --- NBR #1481: computePayloadByteSegmentation ---
function computePayloadByteSegmentation(bytes, opts) {
  if (!bytes || bytes.length === 0) return { segments: [], segmentCount: 0 };
  const o = Object.assign({ threshold: 30 }, opts || {});
  const segments = [];
  let segStart = 0;
  for (let i = 1; i < bytes.length; i++) {
    if (Math.abs(bytes[i] - bytes[i - 1]) > o.threshold) {
      segments.push({ start: segStart, end: i - 1, length: i - segStart });
      segStart = i;
    }
  }
  segments.push({ start: segStart, end: bytes.length - 1, length: bytes.length - segStart });
  return { segments: segments, segmentCount: segments.length };
}

// --- NBR #1482: createDecodeResultPrioritySet ---
function createDecodeResultPrioritySet(opts) {
  const o = Object.assign({ maxSize: 100 }, opts || {});
  const items = [];
  function findIdx(id) {
    for (let i = 0; i < items.length; i++) if (items[i].id === id) return i;
    return -1;
  }
  return {
    add(id, priority) {
      const idx = findIdx(id);
      if (idx >= 0) { items[idx].priority = priority; }
      else {
        items.push({ id: id, priority: priority });
        if (items.length > o.maxSize) {
          items.sort((a, b) => b.priority - a.priority);
          items.length = o.maxSize;
        }
      }
    },
    top(n) {
      const sorted = items.slice().sort((a, b) => b.priority - a.priority);
      return sorted.slice(0, n || 1);
    },
    has(id) { return findIdx(id) >= 0; },
    count() { return items.length; },
    remove(id) {
      const idx = findIdx(id);
      if (idx >= 0) items.splice(idx, 1);
    }
  };
}

// --- NBR #1483: computePayloadByteLocalVariance ---
function computePayloadByteLocalVariance(bytes, opts) {
  if (!bytes || bytes.length === 0) return { variances: [], avgVariance: 0, maxVariance: 0 };
  const o = Object.assign({ windowSize: 5 }, opts || {});
  const w = Math.max(1, o.windowSize);
  const half = Math.floor(w / 2);
  const variances = [];
  for (let i = 0; i < bytes.length; i++) {
    const lo = Math.max(0, i - half);
    const hi = Math.min(bytes.length - 1, i + half);
    let sum = 0, count = 0;
    for (let j = lo; j <= hi; j++) { sum += bytes[j]; count++; }
    const mean = sum / count;
    let vsum = 0;
    for (let j = lo; j <= hi; j++) vsum += (bytes[j] - mean) * (bytes[j] - mean);
    variances.push(vsum / count);
  }
  const avgVariance = variances.reduce((s, v) => s + v, 0) / variances.length;
  const maxVariance = Math.max.apply(null, variances);
  return { variances: variances, avgVariance: avgVariance, maxVariance: maxVariance };
}

// --- NBR #1484: createConfigDecodeRouter ---
function createConfigDecodeRouter(opts) {
  const o = Object.assign({}, opts || {});
  const routes = [];
  return {
    addRoute(pattern, handler) { routes.push({ pattern: pattern, handler: handler }); },
    route(key) {
      for (let i = 0; i < routes.length; i++) {
        if (typeof routes[i].pattern === "string" && key === routes[i].pattern) return routes[i].handler;
        if (routes[i].pattern instanceof RegExp && routes[i].pattern.test(key)) return routes[i].handler;
      }
      return null;
    },
    routeCount() { return routes.length; },
    match(key) {
      const handler = this.route(key);
      if (!handler) return { matched: false, result: null };
      return { matched: true, result: handler(key) };
    }
  };
}

// --- NBR #1485: computePayloadByteConvolution ---
function computePayloadByteConvolution(bytes, kernel, opts) {
  if (!bytes || bytes.length === 0 || !kernel || kernel.length === 0) return { result: [], kernelSum: 0 };
  const o = Object.assign({ normalize: true }, opts || {});
  const kSum = kernel.reduce((s, v) => s + v, 0);
  const norm = (o.normalize && kSum !== 0) ? kSum : 1;
  const half = Math.floor(kernel.length / 2);
  const result = [];
  for (let i = 0; i < bytes.length; i++) {
    let sum = 0;
    for (let k = 0; k < kernel.length; k++) {
      const idx = i - half + k;
      const val = idx < 0 ? bytes[0] : (idx >= bytes.length ? bytes[bytes.length - 1] : bytes[idx]);
      sum += val * kernel[k];
    }
    result.push(sum / norm);
  }
  return { result: result, kernelSum: kSum };
}

// --- NBR #1486: createDecodeResultTrie ---
function createDecodeResultTrie(opts) {
  const o = Object.assign({}, opts || {});
  const root = { children: {}, end: false, value: null };
  let wordCount = 0;
  return {
    insert(key, value) {
      let node = root;
      for (let i = 0; i < key.length; i++) {
        const ch = key[i];
        if (!node.children[ch]) node.children[ch] = { children: {}, end: false, value: null };
        node = node.children[ch];
      }
      if (!node.end) wordCount++;
      node.end = true;
      node.value = value;
    },
    search(key) {
      let node = root;
      for (let i = 0; i < key.length; i++) {
        if (!node.children[key[i]]) return null;
        node = node.children[key[i]];
      }
      return node.end ? node.value : null;
    },
    startsWith(prefix) {
      let node = root;
      for (let i = 0; i < prefix.length; i++) {
        if (!node.children[prefix[i]]) return false;
        node = node.children[prefix[i]];
      }
      return true;
    },
    count() { return wordCount; }
  };
}

// --- NBR #1487: computePayloadByteQuantize ---
function computePayloadByteQuantize(bytes, opts) {
  if (!bytes || bytes.length === 0) return { quantized: [], levels: 0, step: 0 };
  const o = Object.assign({ levels: 4 }, opts || {});
  const levels = Math.max(2, o.levels);
  const min = Math.min.apply(null, bytes);
  const max = Math.max.apply(null, bytes);
  const range = max - min;
  const step = range / levels;
  const quantized = bytes.map(v => {
    if (step === 0) return min;
    const level = Math.min(Math.floor((v - min) / step), levels - 1);
    return min + (level + 0.5) * step;
  });
  return { quantized: quantized, levels: levels, step: step };
}

// --- NBR #1488: createConfigDecodeObserver ---
function createConfigDecodeObserver(opts) {
  const o = Object.assign({}, opts || {});
  const listeners = new Map();
  return {
    on(event, fn) {
      if (!listeners.has(event)) listeners.set(event, []);
      listeners.get(event).push(fn);
    },
    emit(event, data) {
      const fns = listeners.get(event) || [];
      const results = [];
      for (let i = 0; i < fns.length; i++) results.push(fns[i](data));
      return results;
    },
    off(event, fn) {
      if (!listeners.has(event)) return;
      const arr = listeners.get(event);
      const idx = arr.indexOf(fn);
      if (idx >= 0) arr.splice(idx, 1);
    },
    listenerCount(event) { return (listeners.get(event) || []).length; },
    eventNames() { return Array.from(listeners.keys()); }
  };
}

// --- NBR #1489: computePayloadByteMedianFilter ---
function computePayloadByteMedianFilter(bytes, opts) {
  if (!bytes || bytes.length === 0) return { filtered: [], windowSize: 0 };
  const o = Object.assign({ windowSize: 3 }, opts || {});
  const w = Math.max(1, o.windowSize | 1); // ensure odd
  const half = Math.floor(w / 2);
  const filtered = [];
  for (let i = 0; i < bytes.length; i++) {
    const lo = Math.max(0, i - half);
    const hi = Math.min(bytes.length - 1, i + half);
    const window = [];
    for (let j = lo; j <= hi; j++) window.push(bytes[j]);
    window.sort((a, b) => a - b);
    filtered.push(window[Math.floor(window.length / 2)]);
  }
  return { filtered: filtered, windowSize: w };
}

// --- NBR #1490: createDecodeResultBloomFilter ---
function createDecodeResultBloomFilter(opts) {
  const o = Object.assign({ size: 1024, hashCount: 3 }, opts || {});
  const bits = new Uint8Array(o.size);
  let addCount = 0;
  function hash(str, seed) {
    let h = seed;
    for (let i = 0; i < str.length; i++) {
      h = ((h << 5) - h + str.charCodeAt(i)) | 0;
    }
    return Math.abs(h) % o.size;
  }
  return {
    add(key) {
      const s = String(key);
      for (let i = 0; i < o.hashCount; i++) bits[hash(s, i * 31 + 7)] = 1;
      addCount++;
    },
    mightContain(key) {
      const s = String(key);
      for (let i = 0; i < o.hashCount; i++) {
        if (!bits[hash(s, i * 31 + 7)]) return false;
      }
      return true;
    },
    count() { return addCount; },
    fillRatio() {
      let set = 0;
      for (let i = 0; i < bits.length; i++) if (bits[i]) set++;
      return set / bits.length;
    }
  };
}

// --- NBR #1491: computePayloadByteDCT ---
function computePayloadByteDCT(bytes, opts) {
  if (!bytes || bytes.length === 0) return { coefficients: [], energy: 0 };
  const N = bytes.length;
  const coefficients = [];
  let energy = 0;
  for (let k = 0; k < N; k++) {
    let sum = 0;
    for (let n = 0; n < N; n++) {
      sum += bytes[n] * Math.cos(Math.PI * k * (2 * n + 1) / (2 * N));
    }
    const scale = k === 0 ? Math.sqrt(1 / N) : Math.sqrt(2 / N);
    const c = sum * scale;
    coefficients.push(c);
    energy += c * c;
  }
  return { coefficients: coefficients, energy: energy };
}

// --- NBR #1492: createConfigDecodeStateMachine ---
function createConfigDecodeStateMachine(initialState, opts) {
  const o = Object.assign({}, opts || {});
  let current = initialState || "idle";
  const transitions = {};
  const history = [current];
  return {
    addTransition(from, event, to) {
      const key = from + ":" + event;
      transitions[key] = to;
    },
    send(event) {
      const key = current + ":" + event;
      if (transitions[key]) {
        current = transitions[key];
        history.push(current);
        return true;
      }
      return false;
    },
    state() { return current; },
    history() { return history.slice(); },
    canSend(event) { return !!(transitions[current + ":" + event]); }
  };
}

// --- NBR #1493: computePayloadByteHammingDistance ---
function computePayloadByteHammingDistance(a, b, opts) {
  if (!a || !b) return { distance: 0, bitDistance: 0, similarity: 1 };
  const len = Math.min(a.length, b.length);
  let byteDist = 0, bitDist = 0;
  for (let i = 0; i < len; i++) {
    if (a[i] !== b[i]) {
      byteDist++;
      let xor = a[i] ^ b[i];
      while (xor) { bitDist += xor & 1; xor >>= 1; }
    }
  }
  byteDist += Math.abs(a.length - b.length);
  const maxLen = Math.max(a.length, b.length);
  return { distance: byteDist, bitDistance: bitDist, similarity: maxLen > 0 ? 1 - byteDist / maxLen : 1 };
}

// --- NBR #1494: createDecodeResultObjectPool ---
function createDecodeResultObjectPool(factory, opts) {
  const o = Object.assign({ maxSize: 50 }, opts || {});
  const pool = [];
  let created = 0, reused = 0;
  return {
    acquire() {
      if (pool.length > 0) { reused++; return pool.pop(); }
      created++;
      return factory();
    },
    release(obj) {
      if (pool.length < o.maxSize) pool.push(obj);
    },
    available() { return pool.length; },
    stats() { return { created: created, reused: reused, pooled: pool.length }; }
  };
}

// --- NBR #1495: computePayloadByteChunkedHash ---
function computePayloadByteChunkedHash(bytes, opts) {
  if (!bytes || bytes.length === 0) return { hashes: [], chunkSize: 0 };
  const o = Object.assign({ chunkSize: 16 }, opts || {});
  const cs = Math.max(1, o.chunkSize);
  const hashes = [];
  for (let i = 0; i < bytes.length; i += cs) {
    const end = Math.min(i + cs, bytes.length);
    let h = 0x811c9dc5;
    for (let j = i; j < end; j++) {
      h ^= bytes[j];
      h = (h * 0x01000193) & 0xffffffff;
    }
    hashes.push(h >>> 0);
  }
  return { hashes: hashes, chunkSize: cs, chunkCount: hashes.length };
}

// --- NBR #1496: createConfigDecodeMapping ---
function createConfigDecodeMapping(opts) {
  const o = Object.assign({}, opts || {});
  const forward = new Map();
  const reverse = new Map();
  return {
    set(key, value) { forward.set(key, value); reverse.set(value, key); },
    get(key) { return forward.get(key); },
    getReverse(value) { return reverse.get(value); },
    has(key) { return forward.has(key); },
    hasValue(value) { return reverse.has(value); },
    size() { return forward.size; },
    keys() { return Array.from(forward.keys()); },
    values() { return Array.from(forward.values()); }
  };
}

// --- NBR #1497: computePayloadByteNormalize ---
function computePayloadByteNormalize(bytes, opts) {
  if (!bytes || bytes.length === 0) return { normalized: [], min: 0, max: 0, range: 0 };
  const o = Object.assign({ targetMin: 0, targetMax: 255 }, opts || {});
  const min = Math.min.apply(null, bytes);
  const max = Math.max.apply(null, bytes);
  const range = max - min;
  const tRange = o.targetMax - o.targetMin;
  const normalized = bytes.map(v => {
    if (range === 0) return o.targetMin + tRange / 2;
    return o.targetMin + ((v - min) / range) * tRange;
  });
  return { normalized: normalized, min: min, max: max, range: range };
}

// --- NBR #1498: createDecodeResultDiffTracker ---
function createDecodeResultDiffTracker(opts) {
  const o = Object.assign({}, opts || {});
  const snapshots = [];
  return {
    snapshot(label, data) {
      snapshots.push({ label: label, data: JSON.parse(JSON.stringify(data)), time: Date.now() });
    },
    diff(idx1, idx2) {
      if (idx1 >= snapshots.length || idx2 >= snapshots.length) return { changes: [] };
      const a = snapshots[idx1].data;
      const b = snapshots[idx2].data;
      const changes = [];
      const allKeys = new Set([...Object.keys(a), ...Object.keys(b)]);
      allKeys.forEach(k => {
        if (JSON.stringify(a[k]) !== JSON.stringify(b[k])) {
          changes.push({ key: k, from: a[k], to: b[k] });
        }
      });
      return { changes: changes, from: snapshots[idx1].label, to: snapshots[idx2].label };
    },
    count() { return snapshots.length; },
    labels() { return snapshots.map(s => s.label); }
  };
}

// --- NBR #1499: computePayloadByteInterleave ---
function computePayloadByteInterleave(bytes, opts) {
  if (!bytes || bytes.length === 0) return { interleaved: [], blockCount: 0 };
  const o = Object.assign({ blocks: 4 }, opts || {});
  const blocks = Math.max(1, Math.min(o.blocks, bytes.length));
  const blockSize = Math.ceil(bytes.length / blocks);
  const interleaved = new Array(bytes.length);
  let outIdx = 0;
  for (let phase = 0; phase < blockSize; phase++) {
    for (let b = 0; b < blocks; b++) {
      const srcIdx = b * blockSize + phase;
      if (srcIdx < bytes.length) interleaved[outIdx++] = bytes[srcIdx];
    }
  }
  return { interleaved: interleaved.slice(0, outIdx), blockCount: blocks };
}

// --- NBR #1500: createConfigDecodeMiddleware ---
function createConfigDecodeMiddleware(opts) {
  const o = Object.assign({}, opts || {});
  const middlewares = [];
  return {
    use(fn) { middlewares.push(fn); },
    execute(input) {
      let result = input;
      for (let i = 0; i < middlewares.length; i++) {
        result = middlewares[i](result);
        if (result === null || result === undefined) break;
      }
      return result;
    },
    count() { return middlewares.length; },
    clear() { middlewares.length = 0; }
  };
}

// --- NBR #1501: computePayloadByteBitPlanes ---
function computePayloadByteBitPlanes(bytes, opts) {
  if (!bytes || bytes.length === 0) return { planes: [], planeCount: 0 };
  const o = Object.assign({ bits: 8 }, opts || {});
  const numBits = Math.min(8, o.bits);
  const planes = [];
  for (let bit = 0; bit < numBits; bit++) {
    const plane = [];
    for (let i = 0; i < bytes.length; i++) {
      plane.push((bytes[i] >> bit) & 1);
    }
    planes.push(plane);
  }
  return { planes: planes, planeCount: planes.length };
}

// --- NBR #1502: createDecodeResultVersionedMap ---
function createDecodeResultVersionedMap(opts) {
  const o = Object.assign({}, opts || {});
  const store = new Map();
  let version = 0;
  const history = [];
  return {
    set(key, value) {
      version++;
      store.set(key, value);
      history.push({ version: version, key: key, value: value, op: "set" });
    },
    get(key) { return store.get(key); },
    has(key) { return store.has(key); },
    version() { return version; },
    historyAt(v) {
      return history.filter(h => h.version <= v);
    },
    size() { return store.size; },
    changelog() { return history.slice(); }
  };
}

// --- NBR #1503: computePayloadByteSpectralFlatness ---
function computePayloadByteSpectralFlatness(bytes, opts) {
  if (!bytes || bytes.length === 0) return { flatness: 0, isNoise: false };
  const N = bytes.length;
  const mean = bytes.reduce((s, v) => s + v, 0) / N;
  // Compute power spectrum approximation
  const power = [];
  for (let k = 0; k < N; k++) {
    let re = 0, im = 0;
    for (let n = 0; n < N; n++) {
      const angle = 2 * Math.PI * k * n / N;
      re += (bytes[n] - mean) * Math.cos(angle);
      im -= (bytes[n] - mean) * Math.sin(angle);
    }
    power.push(re * re + im * im);
  }
  const half = Math.floor(N / 2);
  const ps = power.slice(1, half + 1);
  if (ps.length === 0) return { flatness: 0, isNoise: false };
  const logSum = ps.reduce((s, v) => s + Math.log(v + 1e-10), 0) / ps.length;
  const arithmeticMean = ps.reduce((s, v) => s + v, 0) / ps.length;
  const geometricMean = Math.exp(logSum);
  const flatness = arithmeticMean > 0 ? geometricMean / arithmeticMean : 0;
  return { flatness: flatness, isNoise: flatness > 0.8 };
}

// --- NBR #1504: createConfigDecodeScheduler ---
function createConfigDecodeScheduler(opts) {
  const o = Object.assign({}, opts || {});
  const tasks = [];
  return {
    schedule(name, priority, fn) {
      tasks.push({ name: name, priority: priority, fn: fn, done: false });
    },
    run() {
      const sorted = tasks.filter(t => !t.done).sort((a, b) => b.priority - a.priority);
      const results = [];
      for (let i = 0; i < sorted.length; i++) {
        sorted[i].done = true;
        results.push({ name: sorted[i].name, result: sorted[i].fn() });
      }
      return results;
    },
    pending() { return tasks.filter(t => !t.done).length; },
    total() { return tasks.length; }
  };
}

// --- NBR #1505: computePayloadByteEntropyCoding ---
function computePayloadByteEntropyCoding(bytes, opts) {
  if (!bytes || bytes.length === 0) return { codebook: {}, avgBits: 0, efficiency: 0 };
  // Build frequency table
  const freq = {};
  for (let i = 0; i < bytes.length; i++) freq[bytes[i]] = (freq[bytes[i]] || 0) + 1;
  // Sort by frequency descending
  const sorted = Object.entries(freq).sort((a, b) => b[1] - a[1]);
  // Simple prefix-free code assignment (Shannon-Fano-like)
  const codebook = {};
  const n = bytes.length;
  let avgBits = 0;
  for (let i = 0; i < sorted.length; i++) {
    const bits = Math.max(1, Math.ceil(Math.log2(sorted.length)));
    codebook[sorted[i][0]] = { freq: sorted[i][1], bits: bits };
    avgBits += (sorted[i][1] / n) * bits;
  }
  const entropy = sorted.reduce((s, e) => {
    const p = e[1] / n;
    return s - p * Math.log2(p);
  }, 0);
  return { codebook: codebook, avgBits: avgBits, entropy: entropy, efficiency: entropy > 0 ? entropy / avgBits : 1 };
}

// --- NBR #1506: createDecodeResultRingQueue ---
function createDecodeResultRingQueue(capacity, opts) {
  const cap = capacity || 16;
  const buf = new Array(cap);
  let head = 0, tail = 0, count = 0;
  return {
    enqueue(val) {
      buf[tail] = val;
      tail = (tail + 1) % cap;
      if (count < cap) count++;
      else head = (head + 1) % cap;
    },
    dequeue() {
      if (count === 0) return undefined;
      const val = buf[head];
      head = (head + 1) % cap;
      count--;
      return val;
    },
    peek() { return count > 0 ? buf[head] : undefined; },
    size() { return count; },
    capacity() { return cap; },
    full() { return count >= cap; }
  };
}

// --- NBR #1507: computePayloadByteWavelet ---
function computePayloadByteWavelet(bytes, opts) {
  if (!bytes || bytes.length < 2) return { approx: [], detail: [], levels: 0 };
  const o = Object.assign({ levels: 1 }, opts || {});
  let data = bytes.slice();
  const details = [];
  let lvl = 0;
  for (let l = 0; l < o.levels && data.length >= 2; l++) {
    const approx = [];
    const detail = [];
    for (let i = 0; i + 1 < data.length; i += 2) {
      approx.push((data[i] + data[i + 1]) / 2);
      detail.push((data[i] - data[i + 1]) / 2);
    }
    details.push(detail);
    data = approx;
    lvl++;
  }
  return { approx: data, detail: details.length > 0 ? details[details.length - 1] : [], levels: lvl, allDetails: details };
}

// --- NBR #1508: createConfigDecodeRegistry ---
function createConfigDecodeRegistry(opts) {
  const o = Object.assign({}, opts || {});
  const registry = new Map();
  return {
    register(name, factory) { registry.set(name, factory); },
    create(name, args) {
      const factory = registry.get(name);
      if (!factory) return null;
      return factory(args);
    },
    has(name) { return registry.has(name); },
    list() { return Array.from(registry.keys()); },
    count() { return registry.size; },
    unregister(name) { registry.delete(name); }
  };
}

// --- NBR #1509: computePayloadByteHistogramBins ---
function computePayloadByteHistogramBins(bytes, opts) {
  if (!bytes || bytes.length === 0) return { bins: [], binCount: 0, mode: 0 };
  const o = Object.assign({ binCount: 16 }, opts || {});
  const numBins = Math.max(1, o.binCount);
  const min = Math.min.apply(null, bytes);
  const max = Math.max.apply(null, bytes);
  const range = max - min || 1;
  const binWidth = range / numBins;
  const bins = new Array(numBins).fill(0);
  for (let i = 0; i < bytes.length; i++) {
    const idx = Math.min(Math.floor((bytes[i] - min) / binWidth), numBins - 1);
    bins[idx]++;
  }
  let maxBin = 0, mode = 0;
  for (let i = 0; i < bins.length; i++) {
    if (bins[i] > maxBin) { maxBin = bins[i]; mode = min + (i + 0.5) * binWidth; }
  }
  return { bins: bins, binCount: numBins, mode: mode, binWidth: binWidth };
}

// --- NBR #1510: createDecodeResultFIFOCache ---
function createDecodeResultFIFOCache(maxSize, opts) {
  const cap = maxSize || 32;
  const keys = [];
  const store = new Map();
  return {
    set(key, value) {
      if (store.has(key)) { store.set(key, value); return; }
      if (keys.length >= cap) {
        const evicted = keys.shift();
        store.delete(evicted);
      }
      keys.push(key);
      store.set(key, value);
    },
    get(key) { return store.get(key); },
    has(key) { return store.has(key); },
    size() { return store.size; },
    capacity() { return cap; },
    evictions() { return Math.max(0, keys.length - store.size); }
  };
}

// --- NBR #1511: computePayloadBytePackBits ---
function computePayloadBytePackBits(bytes, opts) {
  if (!bytes || bytes.length === 0) return { packed: [], ratio: 0 };
  const packed = [];
  let i = 0;
  while (i < bytes.length) {
    // Check for run
    let runLen = 1;
    while (i + runLen < bytes.length && bytes[i + runLen] === bytes[i] && runLen < 128) runLen++;
    if (runLen >= 3) {
      packed.push(257 - runLen); // run marker
      packed.push(bytes[i]);
      i += runLen;
    } else {
      // Literal
      let litLen = 0;
      const litStart = i;
      while (i + litLen < bytes.length && litLen < 128) {
        if (i + litLen + 2 < bytes.length && bytes[i + litLen] === bytes[i + litLen + 1] && bytes[i + litLen] === bytes[i + litLen + 2]) break;
        litLen++;
      }
      if (litLen === 0) litLen = 1;
      packed.push(litLen - 1);
      for (let j = 0; j < litLen; j++) packed.push(bytes[litStart + j]);
      i = litStart + litLen;
    }
  }
  return { packed: packed, ratio: bytes.length / Math.max(1, packed.length) };
}

// --- NBR #1512: createConfigDecodeCompositor ---
function createConfigDecodeCompositor(opts) {
  const o = Object.assign({}, opts || {});
  const layers = [];
  return {
    addLayer(name, config) { layers.push({ name: name, config: Object.assign({}, config) }); },
    compose() {
      const result = {};
      for (let i = 0; i < layers.length; i++) {
        Object.assign(result, layers[i].config);
      }
      return result;
    },
    layerCount() { return layers.length; },
    getLayer(name) {
      for (let i = 0; i < layers.length; i++) if (layers[i].name === name) return layers[i].config;
      return null;
    },
    removeLayer(name) {
      for (let i = 0; i < layers.length; i++) {
        if (layers[i].name === name) { layers.splice(i, 1); return true; }
      }
      return false;
    }
  };
}

// --- NBR #1513: computePayloadByteEdgeDetect ---
function computePayloadByteEdgeDetect(bytes, opts) {
  if (!bytes || bytes.length < 2) return { edges: [], edgeCount: 0, maxEdge: 0 };
  const o = Object.assign({ threshold: 20 }, opts || {});
  const edges = [];
  let maxEdge = 0;
  for (let i = 0; i < bytes.length - 1; i++) {
    const diff = Math.abs(bytes[i + 1] - bytes[i]);
    if (diff >= o.threshold) {
      edges.push({ index: i, magnitude: diff });
      if (diff > maxEdge) maxEdge = diff;
    }
  }
  return { edges: edges, edgeCount: edges.length, maxEdge: maxEdge };
}

// --- NBR #1514: createDecodeResultDeque ---
function createDecodeResultDeque(opts) {
  const o = Object.assign({}, opts || {});
  const items = [];
  return {
    pushFront(val) { items.unshift(val); },
    pushBack(val) { items.push(val); },
    popFront() { return items.shift(); },
    popBack() { return items.pop(); },
    peekFront() { return items.length > 0 ? items[0] : undefined; },
    peekBack() { return items.length > 0 ? items[items.length - 1] : undefined; },
    size() { return items.length; },
    toArray() { return items.slice(); }
  };
}

// --- NBR #1515: computePayloadByteKurtosisMap ---
function computePayloadByteKurtosisMap(bytes, opts) {
  if (!bytes || bytes.length < 4) return { kurtosisValues: [], avgKurtosis: 0 };
  const o = Object.assign({ windowSize: 8 }, opts || {});
  const w = Math.max(4, o.windowSize);
  const half = Math.floor(w / 2);
  const kurtosisValues = [];
  for (let i = 0; i < bytes.length; i++) {
    const lo = Math.max(0, i - half);
    const hi = Math.min(bytes.length - 1, i + half);
    let sum = 0, cnt = 0;
    for (let j = lo; j <= hi; j++) { sum += bytes[j]; cnt++; }
    const mean = sum / cnt;
    let m2 = 0, m4 = 0;
    for (let j = lo; j <= hi; j++) { const d = bytes[j] - mean; m2 += d * d; m4 += d * d * d * d; }
    m2 /= cnt; m4 /= cnt;
    const k = m2 > 0 ? m4 / (m2 * m2) - 3 : 0;
    kurtosisValues.push(k);
  }
  const avgKurtosis = kurtosisValues.reduce((s, v) => s + v, 0) / kurtosisValues.length;
  return { kurtosisValues: kurtosisValues, avgKurtosis: avgKurtosis };
}

// --- NBR #1516: createConfigDecodeThrottler ---
function createConfigDecodeThrottler(opts) {
  const o = Object.assign({ maxPerSecond: 100, windowMs: 1000 }, opts || {});
  const timestamps = [];
  return {
    tryAcquire() {
      const now = Date.now();
      while (timestamps.length > 0 && now - timestamps[0] > o.windowMs) timestamps.shift();
      if (timestamps.length < o.maxPerSecond) { timestamps.push(now); return true; }
      return false;
    },
    currentRate() { return timestamps.length; },
    reset() { timestamps.length = 0; },
    limit() { return o.maxPerSecond; }
  };
}

// --- NBR #1517: computePayloadByteDifferentialEncode ---
function computePayloadByteDifferentialEncode(bytes, opts) {
  if (!bytes || bytes.length === 0) return { encoded: [], decoded: [] };
  const encoded = [bytes[0]];
  for (let i = 1; i < bytes.length; i++) encoded.push(bytes[i] - bytes[i - 1]);
  const decoded = [encoded[0]];
  for (let i = 1; i < encoded.length; i++) decoded.push(decoded[i - 1] + encoded[i]);
  return { encoded: encoded, decoded: decoded, lossless: true };
}

// --- NBR #1518: createDecodeResultSkipList ---
function createDecodeResultSkipList(opts) {
  const o = Object.assign({ maxLevel: 4 }, opts || {});
  const items = [];
  return {
    insert(key, value) {
      const entry = { key: key, value: value };
      // Binary search insert position
      let lo = 0, hi = items.length;
      while (lo < hi) { const mid = (lo + hi) >>> 1; items[mid].key < key ? lo = mid + 1 : hi = mid; }
      items.splice(lo, 0, entry);
    },
    find(key) {
      let lo = 0, hi = items.length - 1;
      while (lo <= hi) {
        const mid = (lo + hi) >>> 1;
        if (items[mid].key === key) return items[mid].value;
        items[mid].key < key ? lo = mid + 1 : hi = mid - 1;
      }
      return undefined;
    },
    range(lo, hi) {
      return items.filter(e => e.key >= lo && e.key <= hi).map(e => e.value);
    },
    size() { return items.length; },
    min() { return items.length > 0 ? items[0] : undefined; },
    max() { return items.length > 0 ? items[items.length - 1] : undefined; }
  };
}

// --- NBR #1519: computePayloadByteMorphClose ---
function computePayloadByteMorphClose(bytes, opts) {
  if (!bytes || bytes.length === 0) return { closed: [] };
  const o = Object.assign({ radius: 1 }, opts || {});
  const r = Math.max(1, o.radius);
  // Dilation then erosion
  const dilated = [];
  for (let i = 0; i < bytes.length; i++) {
    let maxVal = bytes[i];
    for (let j = Math.max(0, i - r); j <= Math.min(bytes.length - 1, i + r); j++) {
      if (bytes[j] > maxVal) maxVal = bytes[j];
    }
    dilated.push(maxVal);
  }
  const closed = [];
  for (let i = 0; i < dilated.length; i++) {
    let minVal = dilated[i];
    for (let j = Math.max(0, i - r); j <= Math.min(dilated.length - 1, i + r); j++) {
      if (dilated[j] < minVal) minVal = dilated[j];
    }
    closed.push(minVal);
  }
  return { closed: closed };
}

// --- NBR #1520: createConfigDecodeSemaphore ---
function createConfigDecodeSemaphore(maxConcurrent, opts) {
  const max = maxConcurrent || 1;
  let current = 0;
  const waiting = [];
  return {
    acquire() {
      if (current < max) { current++; return true; }
      return false;
    },
    release() {
      if (current > 0) current--;
      return current;
    },
    available() { return max - current; },
    inUse() { return current; },
    maxPermits() { return max; }
  };
}

// --- NBR #1521: computePayloadByteChiSquared ---
function computePayloadByteChiSquared(bytes, opts) {
  if (!bytes || bytes.length === 0) return { chiSquared: 0, pValue: 0, isUniform: false };
  const o = Object.assign({ bins: 256 }, opts || {});
  const numBins = Math.min(256, o.bins);
  const expected = bytes.length / numBins;
  const observed = new Array(numBins).fill(0);
  for (let i = 0; i < bytes.length; i++) {
    const bin = Math.min(numBins - 1, Math.floor(bytes[i] * numBins / 256));
    observed[bin]++;
  }
  let chiSq = 0;
  for (let i = 0; i < numBins; i++) {
    if (expected > 0) chiSq += (observed[i] - expected) * (observed[i] - expected) / expected;
  }
  // Rough p-value approximation
  const df = numBins - 1;
  const isUniform = chiSq < df * 2;
  return { chiSquared: chiSq, degreesOfFreedom: df, isUniform: isUniform };
}

// --- NBR #1522: createDecodeResultSortedSet ---
function createDecodeResultSortedSet(compareFn, opts) {
  const cmp = compareFn || ((a, b) => a - b);
  const items = [];
  return {
    add(val) {
      let lo = 0, hi = items.length;
      while (lo < hi) { const mid = (lo + hi) >>> 1; cmp(items[mid], val) < 0 ? lo = mid + 1 : hi = mid; }
      if (lo < items.length && cmp(items[lo], val) === 0) return false;
      items.splice(lo, 0, val);
      return true;
    },
    has(val) {
      let lo = 0, hi = items.length - 1;
      while (lo <= hi) {
        const mid = (lo + hi) >>> 1;
        const c = cmp(items[mid], val);
        if (c === 0) return true;
        c < 0 ? lo = mid + 1 : hi = mid - 1;
      }
      return false;
    },
    remove(val) {
      let lo = 0, hi = items.length - 1;
      while (lo <= hi) {
        const mid = (lo + hi) >>> 1;
        const c = cmp(items[mid], val);
        if (c === 0) { items.splice(mid, 1); return true; }
        c < 0 ? lo = mid + 1 : hi = mid - 1;
      }
      return false;
    },
    size() { return items.length; },
    toArray() { return items.slice(); },
    first() { return items[0]; },
    last() { return items[items.length - 1]; }
  };
}

// --- NBR #1523: computePayloadByteRollingHash ---
function computePayloadByteRollingHash(bytes, opts) {
  if (!bytes || bytes.length === 0) return { hashes: [], windowSize: 0 };
  const o = Object.assign({ windowSize: 4, base: 256, mod: 1000000007 }, opts || {});
  const w = Math.min(o.windowSize, bytes.length);
  const base = o.base;
  const mod = o.mod;
  let basePow = 1;
  for (let i = 0; i < w - 1; i++) basePow = (basePow * base) % mod;
  let hash = 0;
  for (let i = 0; i < w; i++) hash = (hash * base + bytes[i]) % mod;
  const hashes = [hash];
  for (let i = w; i < bytes.length; i++) {
    hash = ((hash - bytes[i - w] * basePow % mod + mod) * base + bytes[i]) % mod;
    hashes.push(hash);
  }
  return { hashes: hashes, windowSize: w };
}

// --- NBR #1524: createConfigDecodeRetryPolicy ---
function createConfigDecodeRetryPolicy(opts) {
  const o = Object.assign({ maxRetries: 3, backoffMs: 100, backoffFactor: 2 }, opts || {});
  return {
    execute(fn) {
      let lastError = null;
      for (let attempt = 0; attempt <= o.maxRetries; attempt++) {
        try {
          return { success: true, result: fn(attempt), attempts: attempt + 1 };
        } catch (e) {
          lastError = e;
        }
      }
      return { success: false, error: lastError ? lastError.message : "unknown", attempts: o.maxRetries + 1 };
    },
    maxRetries() { return o.maxRetries; },
    getDelay(attempt) { return o.backoffMs * Math.pow(o.backoffFactor, attempt); }
  };
}

// --- NBR #1525: computePayloadByteSymmetry ---
function computePayloadByteSymmetry(bytes, opts) {
  if (!bytes || bytes.length < 2) return { symmetryScore: 1, isPalindrome: true };
  const n = bytes.length;
  let matches = 0;
  const half = Math.floor(n / 2);
  for (let i = 0; i < half; i++) {
    if (bytes[i] === bytes[n - 1 - i]) matches++;
  }
  const symmetryScore = matches / half;
  return { symmetryScore: symmetryScore, isPalindrome: matches === half, matchedPairs: matches, totalPairs: half };
}

// --- NBR #1526: createDecodeResultBitVector ---
function createDecodeResultBitVector(size, opts) {
  const n = size || 64;
  const words = new Uint32Array(Math.ceil(n / 32));
  let setBits = 0;
  return {
    set(idx) {
      if (idx >= 0 && idx < n) {
        const w = idx >>> 5, b = idx & 31;
        if (!(words[w] & (1 << b))) { words[w] |= (1 << b); setBits++; }
      }
    },
    clear(idx) {
      if (idx >= 0 && idx < n) {
        const w = idx >>> 5, b = idx & 31;
        if (words[w] & (1 << b)) { words[w] &= ~(1 << b); setBits--; }
      }
    },
    get(idx) {
      if (idx < 0 || idx >= n) return false;
      return !!(words[idx >>> 5] & (1 << (idx & 31)));
    },
    popcount() { return setBits; },
    size() { return n; },
    density() { return setBits / n; }
  };
}

// --- NBR #1527: computePayloadByteOutlierDetect ---
function computePayloadByteOutlierDetect(bytes, opts) {
  if (!bytes || bytes.length < 3) return { outliers: [], outlierCount: 0, threshold: 0 };
  const o = Object.assign({ sigma: 2 }, opts || {});
  const mean = bytes.reduce((s, v) => s + v, 0) / bytes.length;
  const variance = bytes.reduce((s, v) => s + (v - mean) * (v - mean), 0) / bytes.length;
  const stddev = Math.sqrt(variance);
  const threshold = o.sigma * stddev;
  const outliers = [];
  for (let i = 0; i < bytes.length; i++) {
    if (Math.abs(bytes[i] - mean) > threshold) {
      outliers.push({ index: i, value: bytes[i], deviation: Math.abs(bytes[i] - mean) / (stddev || 1) });
    }
  }
  return { outliers: outliers, outlierCount: outliers.length, threshold: threshold, mean: mean, stddev: stddev };
}

// --- NBR #1528: createConfigDecodeEventLog ---
function createConfigDecodeEventLog(opts) {
  const o = Object.assign({ maxEvents: 1000 }, opts || {});
  const events = [];
  return {
    log(type, data) {
      if (events.length >= o.maxEvents) events.shift();
      events.push({ type: type, data: data, time: Date.now() });
    },
    filter(type) { return events.filter(e => e.type === type); },
    last(n) { return events.slice(-(n || 1)); },
    count() { return events.length; },
    clear() { events.length = 0; },
    types() { return [...new Set(events.map(e => e.type))]; }
  };
}

// --- NBR #1529: computePayloadByteLinearRegression ---
function computePayloadByteLinearRegression(bytes, opts) {
  if (!bytes || bytes.length < 2) return { slope: 0, intercept: 0, rSquared: 0 };
  const n = bytes.length;
  let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
  for (let i = 0; i < n; i++) { sumX += i; sumY += bytes[i]; sumXY += i * bytes[i]; sumX2 += i * i; }
  const denom = n * sumX2 - sumX * sumX;
  if (denom === 0) return { slope: 0, intercept: bytes[0], rSquared: 0 };
  const slope = (n * sumXY - sumX * sumY) / denom;
  const intercept = (sumY - slope * sumX) / n;
  const meanY = sumY / n;
  let ssRes = 0, ssTot = 0;
  for (let i = 0; i < n; i++) {
    const pred = slope * i + intercept;
    ssRes += (bytes[i] - pred) * (bytes[i] - pred);
    ssTot += (bytes[i] - meanY) * (bytes[i] - meanY);
  }
  const rSquared = ssTot > 0 ? 1 - ssRes / ssTot : 1;
  return { slope: slope, intercept: intercept, rSquared: rSquared };
}

// --- NBR #1530: createDecodeResultWeightedGraph ---
function createDecodeResultWeightedGraph(opts) {
  const o = Object.assign({ directed: false }, opts || {});
  const adj = new Map();
  let edgeCount = 0;
  return {
    addNode(id) { if (!adj.has(id)) adj.set(id, []); },
    addEdge(from, to, weight) {
      if (!adj.has(from)) adj.set(from, []);
      if (!adj.has(to)) adj.set(to, []);
      adj.get(from).push({ to: to, weight: weight !== undefined ? weight : 1 });
      if (!o.directed) adj.get(to).push({ to: from, weight: weight !== undefined ? weight : 1 });
      edgeCount++;
    },
    neighbors(id) { return (adj.get(id) || []).slice(); },
    nodeCount() { return adj.size; },
    edgeCount() { return edgeCount; },
    nodes() { return Array.from(adj.keys()); }
  };
}

// --- NBR #1531: computePayloadByteMinMaxScale ---
function computePayloadByteMinMaxScale(bytes, opts) {
  if (!bytes || bytes.length === 0) return { scaled: [], oldMin: 0, oldMax: 0 };
  const o = Object.assign({ newMin: 0, newMax: 1 }, opts || {});
  const oldMin = Math.min.apply(null, bytes);
  const oldMax = Math.max.apply(null, bytes);
  const oldRange = oldMax - oldMin;
  const newRange = o.newMax - o.newMin;
  const scaled = bytes.map(v => {
    if (oldRange === 0) return o.newMin + newRange / 2;
    return o.newMin + ((v - oldMin) / oldRange) * newRange;
  });
  return { scaled: scaled, oldMin: oldMin, oldMax: oldMax };
}

// --- NBR #1532: createConfigDecodeFeatureFlag ---
function createConfigDecodeFeatureFlag(opts) {
  const o = Object.assign({}, opts || {});
  const flags = new Map();
  return {
    define(name, defaultVal) { if (!flags.has(name)) flags.set(name, { value: defaultVal, overridden: false }); },
    set(name, val) {
      if (!flags.has(name)) flags.set(name, { value: val, overridden: true });
      else { flags.get(name).value = val; flags.get(name).overridden = true; }
    },
    enabled(name) { const f = flags.get(name); return f ? !!f.value : false; },
    get(name) { const f = flags.get(name); return f ? f.value : undefined; },
    list() { const result = {}; flags.forEach((v, k) => { result[k] = v.value; }); return result; },
    count() { return flags.size; }
  };
}

// --- NBR #1533: computePayloadByteCovariance ---
function computePayloadByteCovariance(a, b, opts) {
  if (!a || !b || a.length === 0 || b.length === 0) return { covariance: 0, correlation: 0 };
  const n = Math.min(a.length, b.length);
  const meanA = a.slice(0, n).reduce((s, v) => s + v, 0) / n;
  const meanB = b.slice(0, n).reduce((s, v) => s + v, 0) / n;
  let cov = 0, varA = 0, varB = 0;
  for (let i = 0; i < n; i++) {
    const da = a[i] - meanA, db = b[i] - meanB;
    cov += da * db; varA += da * da; varB += db * db;
  }
  cov /= n; varA /= n; varB /= n;
  const stdA = Math.sqrt(varA), stdB = Math.sqrt(varB);
  const correlation = (stdA > 0 && stdB > 0) ? cov / (stdA * stdB) : 0;
  return { covariance: cov, correlation: correlation, meanA: meanA, meanB: meanB };
}

// --- NBR #1534: createDecodeResultIntervalTree ---
function createDecodeResultIntervalTree(opts) {
  const o = Object.assign({}, opts || {});
  const intervals = [];
  return {
    insert(lo, hi, data) { intervals.push({ lo: lo, hi: hi, data: data }); },
    query(point) {
      return intervals.filter(iv => point >= iv.lo && point <= iv.hi).map(iv => iv.data);
    },
    overlap(lo, hi) {
      return intervals.filter(iv => iv.lo <= hi && iv.hi >= lo).map(iv => iv.data);
    },
    count() { return intervals.length; },
    remove(lo, hi) {
      for (let i = intervals.length - 1; i >= 0; i--) {
        if (intervals[i].lo === lo && intervals[i].hi === hi) { intervals.splice(i, 1); return true; }
      }
      return false;
    }
  };
}

// --- NBR #1535: computePayloadByteMovingMedian ---
function computePayloadByteMovingMedian(bytes, opts) {
  if (!bytes || bytes.length === 0) return { medians: [] };
  const o = Object.assign({ windowSize: 5 }, opts || {});
  const w = Math.max(1, o.windowSize | 1);
  const half = Math.floor(w / 2);
  const medians = [];
  for (let i = 0; i < bytes.length; i++) {
    const lo = Math.max(0, i - half);
    const hi = Math.min(bytes.length - 1, i + half);
    const win = [];
    for (let j = lo; j <= hi; j++) win.push(bytes[j]);
    win.sort((a, b) => a - b);
    medians.push(win[Math.floor(win.length / 2)]);
  }
  return { medians: medians };
}

// --- NBR #1536: createConfigDecodeBlacklist ---
function createConfigDecodeBlacklist(opts) {
  const o = Object.assign({}, opts || {});
  const blocked = new Set();
  const reasons = new Map();
  return {
    add(key, reason) { blocked.add(key); if (reason) reasons.set(key, reason); },
    isBlocked(key) { return blocked.has(key); },
    reason(key) { return reasons.get(key) || null; },
    remove(key) { blocked.delete(key); reasons.delete(key); },
    list() { return Array.from(blocked); },
    count() { return blocked.size; }
  };
}

// --- NBR #1537: computePayloadByteRepetitionRate ---
function computePayloadByteRepetitionRate(bytes, opts) {
  if (!bytes || bytes.length < 2) return { rate: 0, maxRepeat: 0, avgRepeat: 0 };
  const o = Object.assign({}, opts || {});
  let totalRepeats = 0, maxRepeat = 0, runCount = 0;
  let i = 0;
  while (i < bytes.length) {
    let run = 1;
    while (i + run < bytes.length && bytes[i + run] === bytes[i]) run++;
    if (run > 1) totalRepeats += run;
    if (run > maxRepeat) maxRepeat = run;
    runCount++;
    i += run;
  }
  return { rate: totalRepeats / bytes.length, maxRepeat: maxRepeat, avgRepeat: bytes.length / runCount, runCount: runCount };
}

// --- NBR #1538: createDecodeResultSparseArray ---
function createDecodeResultSparseArray(size, opts) {
  const o = Object.assign({ defaultValue: 0 }, opts || {});
  const store = new Map();
  const capacity = size || 1024;
  return {
    set(idx, val) { if (idx >= 0 && idx < capacity) store.set(idx, val); },
    get(idx) { return store.has(idx) ? store.get(idx) : o.defaultValue; },
    has(idx) { return store.has(idx); },
    delete(idx) { store.delete(idx); },
    nonZeroCount() { return store.size; },
    density() { return store.size / capacity; },
    capacity() { return capacity; },
    entries() { return Array.from(store.entries()); }
  };
}

// --- NBR #1539: computePayloadByteTrendline ---
function computePayloadByteTrendline(bytes, opts) {
  if (!bytes || bytes.length < 2) return { trend: "flat", slope: 0, confidence: 0 };
  const n = bytes.length;
  let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
  for (let i = 0; i < n; i++) { sumX += i; sumY += bytes[i]; sumXY += i * bytes[i]; sumX2 += i * i; }
  const denom = n * sumX2 - sumX * sumX;
  const slope = denom !== 0 ? (n * sumXY - sumX * sumY) / denom : 0;
  const meanY = sumY / n;
  let ssRes = 0, ssTot = 0;
  const intercept = (sumY - slope * sumX) / n;
  for (let i = 0; i < n; i++) {
    ssRes += (bytes[i] - (slope * i + intercept)) * (bytes[i] - (slope * i + intercept));
    ssTot += (bytes[i] - meanY) * (bytes[i] - meanY);
  }
  const r2 = ssTot > 0 ? 1 - ssRes / ssTot : 0;
  const trend = Math.abs(slope) < 0.5 ? "flat" : (slope > 0 ? "increasing" : "decreasing");
  return { trend: trend, slope: slope, confidence: r2 };
}

// --- NBR #1540: createConfigDecodeTokenBucket ---
function createConfigDecodeTokenBucket(opts) {
  const o = Object.assign({ capacity: 10, refillRate: 1, refillInterval: 100 }, opts || {});
  let tokens = o.capacity;
  let lastRefill = Date.now();
  return {
    consume(n) {
      const now = Date.now();
      const elapsed = now - lastRefill;
      const refilled = Math.floor(elapsed / o.refillInterval) * o.refillRate;
      tokens = Math.min(o.capacity, tokens + refilled);
      if (refilled > 0) lastRefill = now;
      const amount = n || 1;
      if (tokens >= amount) { tokens -= amount; return true; }
      return false;
    },
    available() { return tokens; },
    capacity() { return o.capacity; },
    reset() { tokens = o.capacity; lastRefill = Date.now(); }
  };
}

// --- NBR #1541: computePayloadByteAutoSegment ---
function computePayloadByteAutoSegment(bytes, opts) {
  if (!bytes || bytes.length < 2) return { segments: [], boundaries: [] };
  const o = Object.assign({ sensitivity: 1.5 }, opts || {});
  const diffs = [];
  for (let i = 1; i < bytes.length; i++) diffs.push(Math.abs(bytes[i] - bytes[i - 1]));
  const meanDiff = diffs.reduce((s, v) => s + v, 0) / diffs.length;
  const stdDiff = Math.sqrt(diffs.reduce((s, v) => s + (v - meanDiff) * (v - meanDiff), 0) / diffs.length);
  const threshold = meanDiff + o.sensitivity * stdDiff;
  const boundaries = [0];
  for (let i = 0; i < diffs.length; i++) {
    if (diffs[i] > threshold) boundaries.push(i + 1);
  }
  boundaries.push(bytes.length);
  const segments = [];
  for (let i = 0; i < boundaries.length - 1; i++) {
    segments.push({ start: boundaries[i], end: boundaries[i + 1] - 1, length: boundaries[i + 1] - boundaries[i] });
  }
  return { segments: segments, boundaries: boundaries.slice(1, -1) };
}

// --- NBR #1542: createDecodeResultLFUCache ---
function createDecodeResultLFUCache(capacity, opts) {
  const cap = capacity || 16;
  const store = new Map();
  const freqs = new Map();
  return {
    get(key) {
      if (!store.has(key)) return undefined;
      freqs.set(key, (freqs.get(key) || 0) + 1);
      return store.get(key);
    },
    set(key, value) {
      if (store.has(key)) { store.set(key, value); freqs.set(key, (freqs.get(key) || 0) + 1); return; }
      if (store.size >= cap) {
        let minKey = null, minFreq = Infinity;
        freqs.forEach((f, k) => { if (f < minFreq) { minFreq = f; minKey = k; } });
        if (minKey !== null) { store.delete(minKey); freqs.delete(minKey); }
      }
      store.set(key, value);
      freqs.set(key, 1);
    },
    has(key) { return store.has(key); },
    size() { return store.size; },
    frequency(key) { return freqs.get(key) || 0; }
  };
}

// --- NBR #1543: computePayloadByteMovingStdDev ---
function computePayloadByteMovingStdDev(bytes, opts) {
  if (!bytes || bytes.length === 0) return { stddevs: [] };
  const o = Object.assign({ windowSize: 5 }, opts || {});
  const w = Math.max(2, o.windowSize);
  const half = Math.floor(w / 2);
  const stddevs = [];
  for (let i = 0; i < bytes.length; i++) {
    const lo = Math.max(0, i - half);
    const hi = Math.min(bytes.length - 1, i + half);
    let sum = 0, cnt = 0;
    for (let j = lo; j <= hi; j++) { sum += bytes[j]; cnt++; }
    const mean = sum / cnt;
    let vsum = 0;
    for (let j = lo; j <= hi; j++) vsum += (bytes[j] - mean) * (bytes[j] - mean);
    stddevs.push(Math.sqrt(vsum / cnt));
  }
  return { stddevs: stddevs };
}

// --- NBR #1544: createConfigDecodeAuditTrail ---
function createConfigDecodeAuditTrail(opts) {
  const o = Object.assign({}, opts || {});
  const entries = [];
  return {
    record(action, details) {
      entries.push({ action: action, details: details, timestamp: Date.now(), seq: entries.length });
    },
    getAll() { return entries.slice(); },
    getByAction(action) { return entries.filter(e => e.action === action); },
    count() { return entries.length; },
    last() { return entries.length > 0 ? entries[entries.length - 1] : null; },
    since(seq) { return entries.filter(e => e.seq > seq); }
  };
}

// --- NBR #1545: computePayloadByteIQR ---
function computePayloadByteIQR(bytes, opts) {
  if (!bytes || bytes.length < 4) return { q1: 0, median: 0, q3: 0, iqr: 0, outliers: [] };
  const sorted = bytes.slice().sort((a, b) => a - b);
  const n = sorted.length;
  const median = n % 2 === 0 ? (sorted[n / 2 - 1] + sorted[n / 2]) / 2 : sorted[Math.floor(n / 2)];
  const lowerHalf = sorted.slice(0, Math.floor(n / 2));
  const upperHalf = sorted.slice(Math.ceil(n / 2));
  const q1 = lowerHalf.length % 2 === 0 ? (lowerHalf[lowerHalf.length / 2 - 1] + lowerHalf[lowerHalf.length / 2]) / 2 : lowerHalf[Math.floor(lowerHalf.length / 2)];
  const q3 = upperHalf.length % 2 === 0 ? (upperHalf[upperHalf.length / 2 - 1] + upperHalf[upperHalf.length / 2]) / 2 : upperHalf[Math.floor(upperHalf.length / 2)];
  const iqr = q3 - q1;
  const o = Object.assign({ factor: 1.5 }, opts || {});
  const lo = q1 - o.factor * iqr;
  const hi = q3 + o.factor * iqr;
  const outliers = bytes.filter(v => v < lo || v > hi);
  return { q1: q1, median: median, q3: q3, iqr: iqr, outliers: outliers };
}

// --- NBR #1546: createDecodeResultDependencyGraph ---
function createDecodeResultDependencyGraph(opts) {
  const o = Object.assign({}, opts || {});
  const deps = new Map();
  return {
    addNode(id) { if (!deps.has(id)) deps.set(id, []); },
    addDependency(from, to) {
      if (!deps.has(from)) deps.set(from, []);
      deps.get(from).push(to);
    },
    getDependencies(id) { return (deps.get(id) || []).slice(); },
    hasCycle() {
      const visited = new Set(), stack = new Set();
      function dfs(node) {
        if (stack.has(node)) return true;
        if (visited.has(node)) return false;
        visited.add(node); stack.add(node);
        for (const dep of (deps.get(node) || [])) { if (dfs(dep)) return true; }
        stack.delete(node);
        return false;
      }
      for (const node of deps.keys()) { if (dfs(node)) return true; }
      return false;
    },
    nodeCount() { return deps.size; },
    topologicalSort() {
      const visited = new Set(), result = [];
      function dfs(node) {
        if (visited.has(node)) return;
        visited.add(node);
        for (const dep of (deps.get(node) || [])) dfs(dep);
        result.push(node);
      }
      for (const node of deps.keys()) dfs(node);
      return result;
    }
  };
}

// --- NBR #1547: computePayloadByteSpread ---
function computePayloadByteSpread(bytes, opts) {
  if (!bytes || bytes.length === 0) return { range: 0, variance: 0, coeffOfVariation: 0 };
  const n = bytes.length;
  const min = Math.min.apply(null, bytes);
  const max = Math.max.apply(null, bytes);
  const range = max - min;
  const mean = bytes.reduce((s, v) => s + v, 0) / n;
  const variance = bytes.reduce((s, v) => s + (v - mean) * (v - mean), 0) / n;
  const stddev = Math.sqrt(variance);
  const coeffOfVariation = mean !== 0 ? stddev / Math.abs(mean) : 0;
  return { range: range, variance: variance, stddev: stddev, coeffOfVariation: coeffOfVariation, min: min, max: max, mean: mean };
}

// --- NBR #1548: createConfigDecodeCircuitBreaker ---
function createConfigDecodeCircuitBreaker(opts) {
  const o = Object.assign({ failureThreshold: 3, resetTimeout: 5000 }, opts || {});
  let failures = 0, state = "closed", lastFailure = 0;
  return {
    execute(fn) {
      if (state === "open") {
        if (Date.now() - lastFailure > o.resetTimeout) { state = "half-open"; }
        else return { success: false, state: "open", error: "circuit open" };
      }
      try {
        const result = fn();
        if (state === "half-open") { state = "closed"; failures = 0; }
        return { success: true, result: result, state: state };
      } catch (e) {
        failures++;
        lastFailure = Date.now();
        if (failures >= o.failureThreshold) state = "open";
        return { success: false, state: state, error: e.message };
      }
    },
    state() { return state; },
    failures() { return failures; },
    reset() { failures = 0; state = "closed"; }
  };
}

// --- NBR #1549: computePayloadByteBurstDetect ---
function computePayloadByteBurstDetect(bytes, opts) {
  if (!bytes || bytes.length < 3) return { bursts: [], burstCount: 0 };
  const o = Object.assign({ threshold: 50, minLength: 2 }, opts || {});
  const mean = bytes.reduce((s, v) => s + v, 0) / bytes.length;
  const bursts = [];
  let burstStart = -1;
  for (let i = 0; i < bytes.length; i++) {
    const isBurst = Math.abs(bytes[i] - mean) > o.threshold;
    if (isBurst && burstStart < 0) burstStart = i;
    if (!isBurst && burstStart >= 0) {
      if (i - burstStart >= o.minLength) {
        bursts.push({ start: burstStart, end: i - 1, length: i - burstStart });
      }
      burstStart = -1;
    }
  }
  if (burstStart >= 0 && bytes.length - burstStart >= o.minLength) {
    bursts.push({ start: burstStart, end: bytes.length - 1, length: bytes.length - burstStart });
  }
  return { bursts: bursts, burstCount: bursts.length };
}

// --- NBR #1550: createDecodeResultDAWG ---
function createDecodeResultDAWG(opts) {
  const o = Object.assign({}, opts || {});
  // Simplified DAWG as a trie with shared suffixes tracking
  const root = { children: {}, end: false };
  let wordCount = 0;
  return {
    insert(word) {
      let node = root;
      for (let i = 0; i < word.length; i++) {
        const ch = word[i];
        if (!node.children[ch]) node.children[ch] = { children: {}, end: false };
        node = node.children[ch];
      }
      if (!node.end) wordCount++;
      node.end = true;
    },
    contains(word) {
      let node = root;
      for (let i = 0; i < word.length; i++) {
        if (!node.children[word[i]]) return false;
        node = node.children[word[i]];
      }
      return node.end;
    },
    prefixCount(prefix) {
      let node = root;
      for (let i = 0; i < prefix.length; i++) {
        if (!node.children[prefix[i]]) return 0;
        node = node.children[prefix[i]];
      }
      function countBelow(n) {
        let c = n.end ? 1 : 0;
        for (const ch in n.children) c += countBelow(n.children[ch]);
        return c;
      }
      return countBelow(node);
    },
    count() { return wordCount; }
  };
}

// --- NBR #1551: computePayloadByteCepstrum ---
function computePayloadByteCepstrum(bytes, opts) {
  if (!bytes || bytes.length < 4) return { cepstrum: [], quefrency: 0 };
  const N = bytes.length;
  const mean = bytes.reduce((s, v) => s + v, 0) / N;
  // Power spectrum
  const power = [];
  for (let k = 0; k < N; k++) {
    let re = 0, im = 0;
    for (let n = 0; n < N; n++) {
      const angle = 2 * Math.PI * k * n / N;
      re += (bytes[n] - mean) * Math.cos(angle);
      im -= (bytes[n] - mean) * Math.sin(angle);
    }
    power.push(Math.log(re * re + im * im + 1e-10));
  }
  // Inverse DFT of log power
  const cepstrum = [];
  let maxVal = -Infinity, maxIdx = 0;
  for (let q = 0; q < Math.floor(N / 2); q++) {
    let sum = 0;
    for (let k = 0; k < N; k++) sum += power[k] * Math.cos(2 * Math.PI * q * k / N);
    const val = sum / N;
    cepstrum.push(val);
    if (q > 1 && val > maxVal) { maxVal = val; maxIdx = q; }
  }
  return { cepstrum: cepstrum, quefrency: maxIdx };
}

// --- NBR #1552: createConfigDecodeSnapshot ---
function createConfigDecodeSnapshot(opts) {
  const o = Object.assign({}, opts || {});
  const snapshots = [];
  return {
    capture(label, state) {
      snapshots.push({ label: label, state: JSON.parse(JSON.stringify(state)), time: Date.now() });
    },
    restore(idx) {
      if (idx < 0 || idx >= snapshots.length) return null;
      return JSON.parse(JSON.stringify(snapshots[idx].state));
    },
    restoreByLabel(label) {
      for (let i = snapshots.length - 1; i >= 0; i--) {
        if (snapshots[i].label === label) return JSON.parse(JSON.stringify(snapshots[i].state));
      }
      return null;
    },
    count() { return snapshots.length; },
    labels() { return snapshots.map(s => s.label); }
  };
}

// --- NBR #1553: computePayloadByteGaborFilter ---
function computePayloadByteGaborFilter(bytes, opts) {
  if (!bytes || bytes.length === 0) return { filtered: [], energy: 0 };
  const o = Object.assign({ frequency: 0.25, sigma: 2 }, opts || {});
  const sigma = o.sigma;
  const freq = o.frequency;
  const kSize = Math.max(3, Math.ceil(sigma * 6) | 1);
  const half = Math.floor(kSize / 2);
  const kernel = [];
  for (let i = -half; i <= half; i++) {
    const gauss = Math.exp(-(i * i) / (2 * sigma * sigma));
    kernel.push(gauss * Math.cos(2 * Math.PI * freq * i));
  }
  const filtered = [];
  let energy = 0;
  for (let i = 0; i < bytes.length; i++) {
    let sum = 0;
    for (let k = 0; k < kernel.length; k++) {
      const idx = i - half + k;
      const val = idx < 0 ? bytes[0] : (idx >= bytes.length ? bytes[bytes.length - 1] : bytes[idx]);
      sum += val * kernel[k];
    }
    filtered.push(sum);
    energy += sum * sum;
  }
  return { filtered: filtered, energy: energy };
}

// --- NBR #1554: createDecodeResultBTreeMap ---
function createDecodeResultBTreeMap(opts) {
  const o = Object.assign({}, opts || {});
  const entries = [];
  function findIdx(key) {
    let lo = 0, hi = entries.length;
    while (lo < hi) { const mid = (lo + hi) >>> 1; entries[mid].key < key ? lo = mid + 1 : hi = mid; }
    return lo;
  }
  return {
    set(key, value) {
      const idx = findIdx(key);
      if (idx < entries.length && entries[idx].key === key) { entries[idx].value = value; }
      else entries.splice(idx, 0, { key: key, value: value });
    },
    get(key) {
      const idx = findIdx(key);
      return (idx < entries.length && entries[idx].key === key) ? entries[idx].value : undefined;
    },
    has(key) { const idx = findIdx(key); return idx < entries.length && entries[idx].key === key; },
    delete(key) {
      const idx = findIdx(key);
      if (idx < entries.length && entries[idx].key === key) { entries.splice(idx, 1); return true; }
      return false;
    },
    size() { return entries.length; },
    range(lo, hi) { return entries.filter(e => e.key >= lo && e.key <= hi); },
    min() { return entries.length > 0 ? entries[0] : undefined; },
    max() { return entries.length > 0 ? entries[entries.length - 1] : undefined; }
  };
}

// --- NBR #1555: computePayloadByteAutoBinHistogram ---
function computePayloadByteAutoBinHistogram(bytes, opts) {
  if (!bytes || bytes.length === 0) return { bins: [], binCount: 0, binEdges: [] };
  // Sturges' rule for bin count
  const autoBins = Math.max(1, Math.ceil(Math.log2(bytes.length) + 1));
  const o = Object.assign({ binCount: autoBins }, opts || {});
  const min = Math.min.apply(null, bytes);
  const max = Math.max.apply(null, bytes);
  const range = max - min || 1;
  const binWidth = range / o.binCount;
  const bins = new Array(o.binCount).fill(0);
  const binEdges = [];
  for (let i = 0; i <= o.binCount; i++) binEdges.push(min + i * binWidth);
  for (let i = 0; i < bytes.length; i++) {
    const idx = Math.min(Math.floor((bytes[i] - min) / binWidth), o.binCount - 1);
    bins[idx]++;
  }
  return { bins: bins, binCount: o.binCount, binEdges: binEdges, binWidth: binWidth };
}

// --- NBR #1556: createConfigDecodeInstrumentation ---
function createConfigDecodeInstrumentation(opts) {
  const o = Object.assign({}, opts || {});
  const counters = new Map();
  const gauges = new Map();
  return {
    increment(name, amount) { counters.set(name, (counters.get(name) || 0) + (amount || 1)); },
    setGauge(name, value) { gauges.set(name, value); },
    getCounter(name) { return counters.get(name) || 0; },
    getGauge(name) { return gauges.get(name) || 0; },
    report() {
      const r = { counters: {}, gauges: {} };
      counters.forEach((v, k) => { r.counters[k] = v; });
      gauges.forEach((v, k) => { r.gauges[k] = v; });
      return r;
    },
    reset() { counters.clear(); gauges.clear(); }
  };
}

// --- NBR #1557: computePayloadByteRankTransform ---
function computePayloadByteRankTransform(bytes, opts) {
  if (!bytes || bytes.length === 0) return { ranks: [], tiedRanks: [] };
  const indexed = bytes.map((v, i) => ({ v: v, i: i }));
  indexed.sort((a, b) => a.v - b.v);
  const ranks = new Array(bytes.length);
  const tiedRanks = new Array(bytes.length);
  let i = 0;
  while (i < indexed.length) {
    let j = i;
    while (j < indexed.length && indexed[j].v === indexed[i].v) j++;
    const avgRank = (i + j - 1) / 2 + 1;
    for (let k = i; k < j; k++) {
      ranks[indexed[k].i] = k + 1;
      tiedRanks[indexed[k].i] = avgRank;
    }
    i = j;
  }
  return { ranks: ranks, tiedRanks: tiedRanks };
}

// --- NBR #1558: createDecodeResultCountMinSketch ---
function createDecodeResultCountMinSketch(opts) {
  const o = Object.assign({ width: 128, depth: 4 }, opts || {});
  const table = [];
  for (let d = 0; d < o.depth; d++) table.push(new Int32Array(o.width));
  function hash(key, seed) {
    let h = seed;
    const s = String(key);
    for (let i = 0; i < s.length; i++) h = ((h << 5) - h + s.charCodeAt(i)) | 0;
    return Math.abs(h) % o.width;
  }
  return {
    add(key, count) {
      const c = count || 1;
      for (let d = 0; d < o.depth; d++) table[d][hash(key, d * 37 + 11)] += c;
    },
    estimate(key) {
      let min = Infinity;
      for (let d = 0; d < o.depth; d++) {
        const val = table[d][hash(key, d * 37 + 11)];
        if (val < min) min = val;
      }
      return min;
    },
    width() { return o.width; },
    depth() { return o.depth; }
  };
}

// --- NBR #1559: computePayloadByteCluster ---
function computePayloadByteCluster(bytes, opts) {
  if (!bytes || bytes.length === 0) return { clusters: [], centroids: [] };
  const o = Object.assign({ k: 2, maxIter: 20 }, opts || {});
  const k = Math.min(o.k, bytes.length);
  // Init centroids by evenly spacing
  let centroids = [];
  const min = Math.min.apply(null, bytes);
  const max = Math.max.apply(null, bytes);
  for (let i = 0; i < k; i++) centroids.push(min + (max - min) * (i + 0.5) / k);
  let assignments = new Array(bytes.length).fill(0);
  for (let iter = 0; iter < o.maxIter; iter++) {
    // Assign
    for (let i = 0; i < bytes.length; i++) {
      let bestD = Infinity, bestC = 0;
      for (let c = 0; c < k; c++) {
        const d = Math.abs(bytes[i] - centroids[c]);
        if (d < bestD) { bestD = d; bestC = c; }
      }
      assignments[i] = bestC;
    }
    // Update centroids
    const sums = new Array(k).fill(0);
    const counts = new Array(k).fill(0);
    for (let i = 0; i < bytes.length; i++) { sums[assignments[i]] += bytes[i]; counts[assignments[i]]++; }
    let changed = false;
    for (let c = 0; c < k; c++) {
      const newC = counts[c] > 0 ? sums[c] / counts[c] : centroids[c];
      if (Math.abs(newC - centroids[c]) > 0.001) changed = true;
      centroids[c] = newC;
    }
    if (!changed) break;
  }
  const clusters = [];
  for (let c = 0; c < k; c++) {
    const members = [];
    for (let i = 0; i < bytes.length; i++) if (assignments[i] === c) members.push(bytes[i]);
    clusters.push(members);
  }
  return { clusters: clusters, centroids: centroids, assignments: assignments };
}

// --- NBR #1560: createConfigDecodeCheckpoint ---
function createConfigDecodeCheckpoint(opts) {
  const o = Object.assign({ maxCheckpoints: 10 }, opts || {});
  const checkpoints = [];
  return {
    save(label, data) {
      if (checkpoints.length >= o.maxCheckpoints) checkpoints.shift();
      checkpoints.push({ label: label, data: JSON.parse(JSON.stringify(data)), time: Date.now() });
    },
    load(label) {
      for (let i = checkpoints.length - 1; i >= 0; i--) {
        if (checkpoints[i].label === label) return JSON.parse(JSON.stringify(checkpoints[i].data));
      }
      return null;
    },
    latest() { return checkpoints.length > 0 ? JSON.parse(JSON.stringify(checkpoints[checkpoints.length - 1].data)) : null; },
    count() { return checkpoints.length; },
    labels() { return checkpoints.map(c => c.label); }
  };
}

// --- NBR #1561: computePayloadByteResample ---
function computePayloadByteResample(bytes, targetLen, opts) {
  if (!bytes || bytes.length === 0 || targetLen <= 0) return { resampled: [] };
  const o = Object.assign({ method: "linear" }, opts || {});
  const resampled = [];
  for (let i = 0; i < targetLen; i++) {
    const srcIdx = i * (bytes.length - 1) / (targetLen - 1 || 1);
    const lo = Math.floor(srcIdx);
    const hi = Math.min(lo + 1, bytes.length - 1);
    const frac = srcIdx - lo;
    resampled.push(bytes[lo] * (1 - frac) + bytes[hi] * frac);
  }
  return { resampled: resampled, originalLength: bytes.length, targetLength: targetLen };
}

// --- NBR #1562: createDecodeResultHyperLogLog ---
function createDecodeResultHyperLogLog(opts) {
  const o = Object.assign({ precision: 10 }, opts || {});
  const m = 1 << o.precision;
  const registers = new Uint8Array(m);
  let count = 0;
  function hash(val) {
    // Murmur-like mixing for better distribution
    let h = 0;
    const s = String(val);
    for (let i = 0; i < s.length; i++) {
      h = ((h << 5) - h + s.charCodeAt(i)) | 0;
      h ^= (h >>> 16);
      h = (h * 0x85ebca6b) | 0;
      h ^= (h >>> 13);
    }
    return h >>> 0;
  }
  function countLeadingZeros(x) {
    let n = 0;
    for (let bit = 31; bit >= 0; bit--) {
      if (x & (1 << bit)) break;
      n++;
    }
    return n;
  }
  return {
    add(val) {
      const h = hash(val);
      const idx = h & (m - 1);
      const w = h >>> o.precision;
      const rho = countLeadingZeros(w) + 1;
      if (rho > registers[idx]) registers[idx] = rho;
      count++;
    },
    estimate() {
      const alpha = m === 16 ? 0.673 : (m === 32 ? 0.697 : (m === 64 ? 0.709 : 0.7213 / (1 + 1.079 / m)));
      let sum = 0;
      for (let i = 0; i < m; i++) sum += Math.pow(2, -registers[i]);
      let est = alpha * m * m / sum;
      // Small range correction
      if (est <= 2.5 * m) {
        let zeros = 0;
        for (let i = 0; i < m; i++) if (registers[i] === 0) zeros++;
        if (zeros > 0) est = m * Math.log(m / zeros);
      }
      return Math.round(est);
    },
    rawCount() { return count; },
    precision() { return o.precision; }
  };
}

// --- NBR #1563: computePayloadByteHilbertCurve ---
function computePayloadByteHilbertCurve(bytes, opts) {
  if (!bytes || bytes.length === 0) return { mapped: [], order: 0 };
  const o = Object.assign({ order: 4 }, opts || {});
  const n = 1 << o.order;
  const total = n * n;
  function d2xy(nn, d) {
    let rx, ry, s, x = 0, y = 0, t = d;
    for (s = 1; s < nn; s *= 2) {
      rx = 1 & (t / 2);
      ry = 1 & (t ^ rx);
      if (ry === 0) { if (rx === 1) { x = s - 1 - x; y = s - 1 - y; } let tmp = x; x = y; y = tmp; }
      x += s * rx;
      y += s * ry;
      t = Math.floor(t / 4);
    }
    return { x: x, y: y };
  }
  const mapped = [];
  const len = Math.min(bytes.length, total);
  for (let i = 0; i < len; i++) {
    const pos = d2xy(n, i);
    mapped.push({ index: i, x: pos.x, y: pos.y, value: bytes[i] });
  }
  return { mapped: mapped, order: o.order, gridSize: n };
}

// --- NBR #1564: createConfigDecodeAssertion ---
function createConfigDecodeAssertion(opts) {
  const o = Object.assign({ throwOnFail: false }, opts || {});
  const results = [];
  return {
    check(name, condition, message) {
      const passed = !!condition;
      results.push({ name: name, passed: passed, message: message || "" });
      if (!passed && o.throwOnFail) throw new Error("Assertion failed: " + name);
      return passed;
    },
    allPassed() { return results.every(r => r.passed); },
    failures() { return results.filter(r => !r.passed); },
    summary() { return { total: results.length, passed: results.filter(r => r.passed).length, failed: results.filter(r => !r.passed).length }; },
    reset() { results.length = 0; }
  };
}

// --- NBR #1565: computePayloadByteZScore ---
function computePayloadByteZScore(bytes, opts) {
  if (!bytes || bytes.length < 2) return { zScores: [], outlierIndices: [] };
  const o = Object.assign({ threshold: 2 }, opts || {});
  const mean = bytes.reduce((s, v) => s + v, 0) / bytes.length;
  const stddev = Math.sqrt(bytes.reduce((s, v) => s + (v - mean) * (v - mean), 0) / bytes.length);
  const zScores = bytes.map(v => stddev > 0 ? (v - mean) / stddev : 0);
  const outlierIndices = [];
  for (let i = 0; i < zScores.length; i++) {
    if (Math.abs(zScores[i]) > o.threshold) outlierIndices.push(i);
  }
  return { zScores: zScores, outlierIndices: outlierIndices, mean: mean, stddev: stddev };
}

// --- NBR #1566: createDecodeResultMatrix ---
function createDecodeResultMatrix(rows, cols, opts) {
  const r = rows || 1, c = cols || 1;
  const data = [];
  for (let i = 0; i < r; i++) data.push(new Array(c).fill(0));
  return {
    get(row, col) { return (row >= 0 && row < r && col >= 0 && col < c) ? data[row][col] : 0; },
    set(row, col, val) { if (row >= 0 && row < r && col >= 0 && col < c) data[row][col] = val; },
    rows() { return r; },
    cols() { return c; },
    fill(val) { for (let i = 0; i < r; i++) for (let j = 0; j < c; j++) data[i][j] = val; },
    sum() { let s = 0; for (let i = 0; i < r; i++) for (let j = 0; j < c; j++) s += data[i][j]; return s; },
    toArray() { return data.map(row => row.slice()); }
  };
}

// --- NBR #1567: computePayloadByteShannonEntropy ---
function computePayloadByteShannonEntropy(bytes, opts) {
  if (!bytes || bytes.length === 0) return { entropy: 0, maxEntropy: 0, efficiency: 0 };
  const freq = {};
  for (let i = 0; i < bytes.length; i++) freq[bytes[i]] = (freq[bytes[i]] || 0) + 1;
  const n = bytes.length;
  let entropy = 0;
  const symbols = Object.keys(freq);
  for (let i = 0; i < symbols.length; i++) {
    const p = freq[symbols[i]] / n;
    if (p > 0) entropy -= p * Math.log2(p);
  }
  const maxEntropy = Math.log2(Math.min(256, n));
  return { entropy: entropy, maxEntropy: maxEntropy, efficiency: maxEntropy > 0 ? entropy / maxEntropy : 0, uniqueSymbols: symbols.length };
}

// --- NBR #1568: createConfigDecodeRateLimiter ---
function createConfigDecodeRateLimiter(opts) {
  const o = Object.assign({ windowMs: 1000, maxCalls: 10 }, opts || {});
  const calls = [];
  return {
    allow() {
      const now = Date.now();
      while (calls.length > 0 && now - calls[0] > o.windowMs) calls.shift();
      if (calls.length < o.maxCalls) { calls.push(now); return true; }
      return false;
    },
    remaining() {
      const now = Date.now();
      while (calls.length > 0 && now - calls[0] > o.windowMs) calls.shift();
      return Math.max(0, o.maxCalls - calls.length);
    },
    reset() { calls.length = 0; },
    limit() { return o.maxCalls; }
  };
}

// --- NBR #1569: computePayloadByteMatrixReshape ---
function computePayloadByteMatrixReshape(bytes, rows, cols, opts) {
  if (!bytes || bytes.length === 0) return { matrix: [], rows: 0, cols: 0 };
  const r = rows || Math.ceil(Math.sqrt(bytes.length));
  const c = cols || Math.ceil(bytes.length / r);
  const matrix = [];
  let idx = 0;
  for (let i = 0; i < r; i++) {
    const row = [];
    for (let j = 0; j < c; j++) {
      row.push(idx < bytes.length ? bytes[idx++] : 0);
    }
    matrix.push(row);
  }
  return { matrix: matrix, rows: r, cols: c, paddedCount: r * c - bytes.length };
}

// --- NBR #1570: createDecodeResultPubSub ---
function createDecodeResultPubSub(opts) {
  const o = Object.assign({}, opts || {});
  const topics = new Map();
  let messageCount = 0;
  return {
    subscribe(topic, fn) {
      if (!topics.has(topic)) topics.set(topic, []);
      topics.get(topic).push(fn);
    },
    publish(topic, data) {
      const subs = topics.get(topic) || [];
      messageCount++;
      for (let i = 0; i < subs.length; i++) subs[i](data);
      return subs.length;
    },
    unsubscribe(topic, fn) {
      if (!topics.has(topic)) return;
      const arr = topics.get(topic);
      const idx = arr.indexOf(fn);
      if (idx >= 0) arr.splice(idx, 1);
    },
    subscriberCount(topic) { return (topics.get(topic) || []).length; },
    totalMessages() { return messageCount; },
    topics() { return Array.from(topics.keys()); }
  };
}

// --- NBR #1571: computePayloadByteVarianceRatio ---
function computePayloadByteVarianceRatio(bytes, opts) {
  if (!bytes || bytes.length < 4) return { ratio: 0, isStationary: true };
  const o = Object.assign({ splitPoint: 0.5 }, opts || {});
  const split = Math.floor(bytes.length * o.splitPoint);
  const first = bytes.slice(0, split);
  const second = bytes.slice(split);
  function variance(arr) {
    const m = arr.reduce((s, v) => s + v, 0) / arr.length;
    return arr.reduce((s, v) => s + (v - m) * (v - m), 0) / arr.length;
  }
  const v1 = variance(first), v2 = variance(second);
  const ratio = v2 > 0 ? v1 / v2 : (v1 === 0 ? 1 : Infinity);
  return { ratio: ratio, variance1: v1, variance2: v2, isStationary: ratio > 0.5 && ratio < 2 };
}

// --- NBR #1572: createConfigDecodeStateStore ---
function createConfigDecodeStateStore(initialState, opts) {
  const o = Object.assign({}, opts || {});
  let state = JSON.parse(JSON.stringify(initialState || {}));
  const subscribers = [];
  return {
    getState() { return JSON.parse(JSON.stringify(state)); },
    setState(partial) {
      state = Object.assign(state, JSON.parse(JSON.stringify(partial)));
      for (let i = 0; i < subscribers.length; i++) subscribers[i](state);
    },
    subscribe(fn) { subscribers.push(fn); return () => { const idx = subscribers.indexOf(fn); if (idx >= 0) subscribers.splice(idx, 1); }; },
    reset(newState) { state = JSON.parse(JSON.stringify(newState || {})); },
    subscriberCount() { return subscribers.length; }
  };
}

// --- NBR #1573: computePayloadByteBlockEntropy ---
function computePayloadByteBlockEntropy(bytes, opts) {
  if (!bytes || bytes.length === 0) return { blockEntropies: [], avgEntropy: 0 };
  const o = Object.assign({ blockSize: 16 }, opts || {});
  const bs = Math.max(1, o.blockSize);
  const blockEntropies = [];
  for (let start = 0; start < bytes.length; start += bs) {
    const end = Math.min(start + bs, bytes.length);
    const block = bytes.slice(start, end);
    const freq = {};
    for (let i = 0; i < block.length; i++) freq[block[i]] = (freq[block[i]] || 0) + 1;
    let entropy = 0;
    const n = block.length;
    Object.values(freq).forEach(f => { const p = f / n; if (p > 0) entropy -= p * Math.log2(p); });
    blockEntropies.push(entropy);
  }
  const avgEntropy = blockEntropies.reduce((s, v) => s + v, 0) / blockEntropies.length;
  return { blockEntropies: blockEntropies, avgEntropy: avgEntropy, blockCount: blockEntropies.length };
}

// --- NBR #1574: createDecodeResultCompactSet ---
function createDecodeResultCompactSet(opts) {
  const o = Object.assign({}, opts || {});
  const items = new Set();
  return {
    add(val) { items.add(val); },
    has(val) { return items.has(val); },
    delete(val) { return items.delete(val); },
    size() { return items.size; },
    toArray() { return Array.from(items); },
    union(otherArr) { const result = new Set(items); otherArr.forEach(v => result.add(v)); return Array.from(result); },
    intersect(otherArr) { return otherArr.filter(v => items.has(v)); },
    difference(otherArr) { const other = new Set(otherArr); return Array.from(items).filter(v => !other.has(v)); }
  };
}

// --- NBR #1575: computePayloadByteFisherInfo ---
function computePayloadByteFisherInfo(bytes, opts) {
  if (!bytes || bytes.length < 2) return { fisherInfo: 0, complexity: 0 };
  let sumSqDiff = 0;
  for (let i = 1; i < bytes.length; i++) {
    const diff = bytes[i] - bytes[i - 1];
    sumSqDiff += diff * diff;
  }
  const fisherInfo = sumSqDiff / (bytes.length - 1);
  const mean = bytes.reduce((s, v) => s + v, 0) / bytes.length;
  const variance = bytes.reduce((s, v) => s + (v - mean) * (v - mean), 0) / bytes.length;
  const complexity = variance > 0 ? fisherInfo / variance : 0;
  return { fisherInfo: fisherInfo, complexity: complexity, variance: variance };
}

// --- NBR #1576: createConfigDecodeTransactionLog ---
function createConfigDecodeTransactionLog(opts) {
  const o = Object.assign({ maxEntries: 500 }, opts || {});
  const log = [];
  let seq = 0;
  return {
    begin(label) { const tx = { id: ++seq, label: label, ops: [], status: "active", start: Date.now() }; log.push(tx); return tx.id; },
    addOp(txId, op) { const tx = log.find(t => t.id === txId); if (tx && tx.status === "active") tx.ops.push(op); },
    commit(txId) { const tx = log.find(t => t.id === txId); if (tx) tx.status = "committed"; },
    rollback(txId) { const tx = log.find(t => t.id === txId); if (tx) tx.status = "rolled_back"; },
    getTransaction(txId) { return log.find(t => t.id === txId) || null; },
    count() { return log.length; },
    committed() { return log.filter(t => t.status === "committed"); }
  };
}

// --- NBR #1577: computePayloadBytePeakToPeak ---
function computePayloadBytePeakToPeak(bytes, opts) {
  if (!bytes || bytes.length === 0) return { peakToPeak: 0, crestFactor: 0 };
  const min = Math.min.apply(null, bytes);
  const max = Math.max.apply(null, bytes);
  const peakToPeak = max - min;
  const rms = Math.sqrt(bytes.reduce((s, v) => s + v * v, 0) / bytes.length);
  const crestFactor = rms > 0 ? max / rms : 0;
  return { peakToPeak: peakToPeak, min: min, max: max, rms: rms, crestFactor: crestFactor };
}

// --- NBR #1578: createDecodeResultConcurrentMap ---
function createDecodeResultConcurrentMap(opts) {
  const o = Object.assign({ shards: 4 }, opts || {});
  const shards = [];
  for (let i = 0; i < o.shards; i++) shards.push(new Map());
  function shard(key) { let h = 0; const s = String(key); for (let i = 0; i < s.length; i++) h = ((h << 5) - h + s.charCodeAt(i)) | 0; return Math.abs(h) % o.shards; }
  return {
    set(key, value) { shards[shard(key)].set(key, value); },
    get(key) { return shards[shard(key)].get(key); },
    has(key) { return shards[shard(key)].has(key); },
    delete(key) { return shards[shard(key)].delete(key); },
    size() { let s = 0; for (let i = 0; i < shards.length; i++) s += shards[i].size; return s; },
    shardCount() { return o.shards; },
    shardSizes() { return shards.map(s => s.size); }
  };
}

// --- NBR #1579: computePayloadByteAutoLevel ---
function computePayloadByteAutoLevel(bytes, opts) {
  if (!bytes || bytes.length === 0) return { leveled: [], clipLow: 0, clipHigh: 255 };
  const o = Object.assign({ clipPercent: 1 }, opts || {});
  const sorted = bytes.slice().sort((a, b) => a - b);
  const clipCount = Math.floor(bytes.length * o.clipPercent / 100);
  const clipLow = sorted[Math.min(clipCount, sorted.length - 1)];
  const clipHigh = sorted[Math.max(sorted.length - 1 - clipCount, 0)];
  const range = clipHigh - clipLow || 1;
  const leveled = bytes.map(v => {
    const clamped = Math.max(clipLow, Math.min(clipHigh, v));
    return Math.round(((clamped - clipLow) / range) * 255);
  });
  return { leveled: leveled, clipLow: clipLow, clipHigh: clipHigh };
}

// --- NBR #1580: createConfigDecodeResourcePool ---
function createConfigDecodeResourcePool(factory, opts) {
  const o = Object.assign({ minSize: 2, maxSize: 10 }, opts || {});
  const available = [];
  const inUse = new Set();
  for (let i = 0; i < o.minSize; i++) available.push(factory());
  return {
    acquire() {
      let resource;
      if (available.length > 0) { resource = available.pop(); }
      else if (inUse.size < o.maxSize) { resource = factory(); }
      else return null;
      inUse.add(resource);
      return resource;
    },
    release(resource) { inUse.delete(resource); available.push(resource); },
    availableCount() { return available.length; },
    inUseCount() { return inUse.size; },
    totalCount() { return available.length + inUse.size; }
  };
}

// --- NBR #1581: computePayloadByteLocalMaxima ---
function computePayloadByteLocalMaxima(bytes, opts) {
  if (!bytes || bytes.length < 3) return { maxima: [], count: 0 };
  const o = Object.assign({ windowSize: 3 }, opts || {});
  const half = Math.floor(o.windowSize / 2);
  const maxima = [];
  for (let i = half; i < bytes.length - half; i++) {
    let isMax = true;
    for (let j = i - half; j <= i + half; j++) {
      if (j !== i && bytes[j] >= bytes[i]) { isMax = false; break; }
    }
    if (isMax) maxima.push({ index: i, value: bytes[i] });
  }
  return { maxima: maxima, count: maxima.length };
}

// --- NBR #1582: createDecodeResultMultiIndex ---
function createDecodeResultMultiIndex(opts) {
  const o = Object.assign({}, opts || {});
  const primary = new Map();
  const indices = new Map();
  let idSeq = 0;
  return {
    addIndex(name, keyFn) { indices.set(name, { keyFn: keyFn, map: new Map() }); },
    insert(record) {
      const id = ++idSeq;
      primary.set(id, record);
      indices.forEach((idx) => {
        const key = idx.keyFn(record);
        if (!idx.map.has(key)) idx.map.set(key, []);
        idx.map.get(key).push(id);
      });
      return id;
    },
    findByIndex(indexName, key) {
      const idx = indices.get(indexName);
      if (!idx) return [];
      const ids = idx.map.get(key) || [];
      return ids.map(id => primary.get(id)).filter(Boolean);
    },
    get(id) { return primary.get(id) || null; },
    size() { return primary.size; }
  };
}

// --- NBR #1583: computePayloadByteSampleEntropy ---
function computePayloadByteSampleEntropy(bytes, opts) {
  if (!bytes || bytes.length < 10) return { sampleEntropy: 0, regularity: 1 };
  const o = Object.assign({ m: 2, r: 0.2 }, opts || {});
  const n = bytes.length;
  const mean = bytes.reduce((s, v) => s + v, 0) / n;
  const stddev = Math.sqrt(bytes.reduce((s, v) => s + (v - mean) * (v - mean), 0) / n);
  const tolerance = o.r * (stddev || 1);
  function countMatches(templateLen) {
    let count = 0;
    for (let i = 0; i <= n - templateLen; i++) {
      for (let j = i + 1; j <= n - templateLen; j++) {
        let match = true;
        for (let k = 0; k < templateLen; k++) {
          if (Math.abs(bytes[i + k] - bytes[j + k]) > tolerance) { match = false; break; }
        }
        if (match) count++;
      }
    }
    return count;
  }
  const A = countMatches(o.m + 1);
  const B = countMatches(o.m);
  const sampleEntropy = B > 0 ? -Math.log(A / B) : 0;
  return { sampleEntropy: sampleEntropy, regularity: Math.exp(-sampleEntropy) };
}

// --- NBR #1584: createConfigDecodeVersionManager ---
function createConfigDecodeVersionManager(opts) {
  const o = Object.assign({}, opts || {});
  const versions = [];
  return {
    addVersion(version, config) {
      versions.push({ version: version, config: JSON.parse(JSON.stringify(config)), time: Date.now() });
    },
    getVersion(version) {
      const v = versions.find(v => v.version === version);
      return v ? JSON.parse(JSON.stringify(v.config)) : null;
    },
    latest() { return versions.length > 0 ? JSON.parse(JSON.stringify(versions[versions.length - 1].config)) : null; },
    latestVersion() { return versions.length > 0 ? versions[versions.length - 1].version : null; },
    list() { return versions.map(v => v.version); },
    count() { return versions.length; }
  };
}

// --- NBR #1585: computePayloadBytePermutationEntropy ---
function computePayloadBytePermutationEntropy(bytes, opts) {
  if (!bytes || bytes.length < 3) return { permutationEntropy: 0, complexity: 0 };
  const o = Object.assign({ order: 3 }, opts || {});
  const order = Math.max(2, Math.min(o.order, 6));
  const patterns = {};
  let total = 0;
  for (let i = 0; i <= bytes.length - order; i++) {
    const window = bytes.slice(i, i + order);
    const indices = window.map((v, idx) => ({ v: v, i: idx })).sort((a, b) => a.v - b.v || a.i - b.i).map(x => x.i);
    const key = indices.join(",");
    patterns[key] = (patterns[key] || 0) + 1;
    total++;
  }
  let entropy = 0;
  const patternKeys = Object.keys(patterns);
  for (let i = 0; i < patternKeys.length; i++) {
    const p = patterns[patternKeys[i]] / total;
    if (p > 0) entropy -= p * Math.log2(p);
  }
  const maxEntropy = Math.log2(factorial(order));
  function factorial(n) { let f = 1; for (let i = 2; i <= n; i++) f *= i; return f; }
  return { permutationEntropy: entropy, normalizedEntropy: maxEntropy > 0 ? entropy / maxEntropy : 0, patternCount: patternKeys.length };
}

// --- NBR #1586: createDecodeResultTimedCache ---
function createDecodeResultTimedCache(ttlMs, opts) {
  const ttl = ttlMs || 5000;
  const store = new Map();
  return {
    set(key, value) { store.set(key, { value: value, expires: Date.now() + ttl }); },
    get(key) {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (Date.now() > entry.expires) { store.delete(key); return undefined; }
      return entry.value;
    },
    has(key) {
      const entry = store.get(key);
      if (!entry) return false;
      if (Date.now() > entry.expires) { store.delete(key); return false; }
      return true;
    },
    size() { return store.size; },
    cleanup() {
      const now = Date.now();
      let removed = 0;
      store.forEach((v, k) => { if (now > v.expires) { store.delete(k); removed++; } });
      return removed;
    },
    ttl() { return ttl; }
  };
}

// --- NBR #1587: computePayloadByteCompressibility ---
function computePayloadByteCompressibility(bytes, opts) {
  if (!bytes || bytes.length === 0) return { ratio: 0, runCount: 0, uniqueRatio: 0 };
  const freq = {};
  let runCount = 1;
  for (let i = 0; i < bytes.length; i++) {
    freq[bytes[i]] = (freq[bytes[i]] || 0) + 1;
    if (i > 0 && bytes[i] !== bytes[i - 1]) runCount++;
  }
  const uniqueCount = Object.keys(freq).length;
  const uniqueRatio = uniqueCount / 256;
  const entropy = Object.values(freq).reduce((s, f) => { const p = f / bytes.length; return s - p * Math.log2(p); }, 0);
  const theoreticalBits = entropy * bytes.length;
  const ratio = bytes.length * 8 > 0 ? theoreticalBits / (bytes.length * 8) : 1;
  return { ratio: ratio, runCount: runCount, uniqueRatio: uniqueRatio, entropy: entropy, uniqueSymbols: uniqueCount };
}

// --- NBR #1588: createConfigDecodeLoadBalancer ---
function createConfigDecodeLoadBalancer(opts) {
  const o = Object.assign({ strategy: "round-robin" }, opts || {});
  const targets = [];
  let rrIndex = 0;
  return {
    addTarget(name, weight) { targets.push({ name: name, weight: weight || 1, load: 0 }); },
    next() {
      if (targets.length === 0) return null;
      if (o.strategy === "round-robin") {
        const t = targets[rrIndex % targets.length];
        rrIndex++;
        t.load++;
        return t.name;
      }
      // least-loaded
      let best = targets[0];
      for (let i = 1; i < targets.length; i++) if (targets[i].load < best.load) best = targets[i];
      best.load++;
      return best.name;
    },
    getLoad(name) { const t = targets.find(t => t.name === name); return t ? t.load : 0; },
    targetCount() { return targets.length; },
    totalLoad() { return targets.reduce((s, t) => s + t.load, 0); }
  };
}

// --- NBR #1589: computePayloadByteAutoCorrelogram ---
function computePayloadByteAutoCorrelogram(bytes, opts) {
  if (!bytes || bytes.length < 4) return { correlogram: [], dominantLag: 0 };
  const o = Object.assign({ maxLag: Math.min(32, Math.floor(bytes.length / 2)) }, opts || {});
  const n = bytes.length;
  const mean = bytes.reduce((s, v) => s + v, 0) / n;
  let c0 = 0;
  for (let i = 0; i < n; i++) c0 += (bytes[i] - mean) * (bytes[i] - mean);
  if (c0 === 0) return { correlogram: new Array(o.maxLag + 1).fill(1), dominantLag: 0 };
  const correlogram = [];
  let bestLag = 1, bestVal = -Infinity;
  for (let lag = 0; lag <= o.maxLag; lag++) {
    let sum = 0;
    for (let i = 0; i < n - lag; i++) sum += (bytes[i] - mean) * (bytes[i + lag] - mean);
    const val = sum / c0;
    correlogram.push(val);
    if (lag > 0 && val > bestVal) { bestVal = val; bestLag = lag; }
  }
  return { correlogram: correlogram, dominantLag: bestLag, peakCorrelation: bestVal };
}

// --- NBR #1590: createDecodeResultWriteAheadLog ---
function createDecodeResultWriteAheadLog(opts) {
  const o = Object.assign({ maxEntries: 1000 }, opts || {});
  const entries = [];
  let lsn = 0;
  return {
    append(op, data) {
      lsn++;
      if (entries.length >= o.maxEntries) entries.shift();
      entries.push({ lsn: lsn, op: op, data: data, time: Date.now() });
      return lsn;
    },
    replay(fromLSN) { return entries.filter(e => e.lsn >= fromLSN); },
    latest() { return entries.length > 0 ? entries[entries.length - 1] : null; },
    currentLSN() { return lsn; },
    count() { return entries.length; },
    truncate(beforeLSN) {
      while (entries.length > 0 && entries[0].lsn < beforeLSN) entries.shift();
    }
  };
}

// --- NBR #1591: computePayloadByteDurbinWatson ---
function computePayloadByteDurbinWatson(bytes, opts) {
  if (!bytes || bytes.length < 3) return { statistic: 2, hasAutoCorrelation: false };
  let sumSqDiff = 0, sumSq = 0;
  const mean = bytes.reduce((s, v) => s + v, 0) / bytes.length;
  for (let i = 0; i < bytes.length; i++) {
    const residual = bytes[i] - mean;
    sumSq += residual * residual;
    if (i > 0) {
      const prevResidual = bytes[i - 1] - mean;
      sumSqDiff += (residual - prevResidual) * (residual - prevResidual);
    }
  }
  const dw = sumSq > 0 ? sumSqDiff / sumSq : 2;
  return { statistic: dw, hasAutoCorrelation: dw < 1.5 || dw > 2.5 };
}

// --- NBR #1592: createConfigDecodeComparator ---
function createConfigDecodeComparator(opts) {
  const o = Object.assign({}, opts || {});
  const configs = [];
  return {
    add(name, config) { configs.push({ name: name, config: config }); },
    compare(idx1, idx2) {
      if (idx1 >= configs.length || idx2 >= configs.length) return { differences: [] };
      const a = configs[idx1].config, b = configs[idx2].config;
      const allKeys = new Set([...Object.keys(a), ...Object.keys(b)]);
      const differences = [];
      allKeys.forEach(k => {
        if (JSON.stringify(a[k]) !== JSON.stringify(b[k])) {
          differences.push({ key: k, valueA: a[k], valueB: b[k] });
        }
      });
      return { nameA: configs[idx1].name, nameB: configs[idx2].name, differences: differences, identical: differences.length === 0 };
    },
    count() { return configs.length; },
    get(idx) { return idx < configs.length ? configs[idx] : null; }
  };
}

// --- NBR #1593: computePayloadByteRunningMax ---
function computePayloadByteRunningMax(bytes, opts) {
  if (!bytes || bytes.length === 0) return { maxValues: [] };
  const o = Object.assign({ windowSize: 5 }, opts || {});
  const w = Math.max(1, o.windowSize);
  const half = Math.floor(w / 2);
  const maxValues = [];
  for (let i = 0; i < bytes.length; i++) {
    const lo = Math.max(0, i - half);
    const hi = Math.min(bytes.length - 1, i + half);
    let maxVal = bytes[lo];
    for (let j = lo + 1; j <= hi; j++) if (bytes[j] > maxVal) maxVal = bytes[j];
    maxValues.push(maxVal);
  }
  return { maxValues: maxValues };
}

// --- NBR #1594: createDecodeResultBitmask ---
function createDecodeResultBitmask(size, opts) {
  const n = size || 32;
  const bytes = new Uint8Array(Math.ceil(n / 8));
  return {
    set(idx) { if (idx >= 0 && idx < n) bytes[idx >>> 3] |= (1 << (idx & 7)); },
    clear(idx) { if (idx >= 0 && idx < n) bytes[idx >>> 3] &= ~(1 << (idx & 7)); },
    test(idx) { return idx >= 0 && idx < n ? !!(bytes[idx >>> 3] & (1 << (idx & 7))) : false; },
    toggle(idx) { if (idx >= 0 && idx < n) bytes[idx >>> 3] ^= (1 << (idx & 7)); },
    popcount() { let c = 0; for (let i = 0; i < n; i++) if (this.test(i)) c++; return c; },
    size() { return n; },
    and(other) { const r = createDecodeResultBitmask(n); for (let i = 0; i < n; i++) if (this.test(i) && other.test(i)) r.set(i); return r; },
    or(other) { const r = createDecodeResultBitmask(n); for (let i = 0; i < n; i++) if (this.test(i) || other.test(i)) r.set(i); return r; }
  };
}

// --- NBR #1595: computePayloadByteGiniCoefficient ---
function computePayloadByteGiniCoefficient(bytes, opts) {
  if (!bytes || bytes.length < 2) return { gini: 0, isEqual: true };
  const sorted = bytes.slice().sort((a, b) => a - b);
  const n = sorted.length;
  const mean = sorted.reduce((s, v) => s + v, 0) / n;
  if (mean === 0) return { gini: 0, isEqual: true };
  let sumAbsDiff = 0;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) sumAbsDiff += Math.abs(sorted[i] - sorted[j]);
  const gini = sumAbsDiff / (2 * n * n * mean);
  return { gini: gini, isEqual: gini < 0.05 };
}

// --- NBR #1596: createConfigDecodePipeline ---
function createConfigDecodePipeline(opts) {
  const o = Object.assign({}, opts || {});
  const stages = [];
  return {
    addStage(name, fn) { stages.push({ name: name, fn: fn }); },
    execute(input) {
      let result = input;
      const timings = [];
      for (let i = 0; i < stages.length; i++) {
        const start = Date.now();
        result = stages[i].fn(result);
        timings.push({ stage: stages[i].name, elapsed: Date.now() - start });
      }
      return { result: result, timings: timings, stageCount: stages.length };
    },
    stageCount() { return stages.length; },
    stageNames() { return stages.map(s => s.name); }
  };
}

// --- NBR #1597: computePayloadByteTheilIndex ---
function computePayloadByteTheilIndex(bytes, opts) {
  if (!bytes || bytes.length < 2) return { theilT: 0, theilL: 0 };
  const n = bytes.length;
  const mean = bytes.reduce((s, v) => s + v, 0) / n;
  if (mean === 0) return { theilT: 0, theilL: 0 };
  let theilT = 0, theilL = 0;
  for (let i = 0; i < n; i++) {
    const ratio = bytes[i] / mean;
    if (ratio > 0) {
      theilT += ratio * Math.log(ratio);
      theilL += Math.log(ratio);
    }
  }
  theilT /= n;
  theilL = -theilL / n;
  return { theilT: theilT, theilL: theilL };
}

// --- NBR #1598: createDecodeResultFenwickTree ---
function createDecodeResultFenwickTree(size, opts) {
  const n = size || 32;
  const tree = new Array(n + 1).fill(0);
  return {
    update(idx, delta) { for (let i = idx + 1; i <= n; i += i & (-i)) tree[i] += delta; },
    query(idx) { let sum = 0; for (let i = idx + 1; i > 0; i -= i & (-i)) sum += tree[i]; return sum; },
    rangeQuery(lo, hi) { return this.query(hi) - (lo > 0 ? this.query(lo - 1) : 0); },
    size() { return n; },
    set(idx, val) {
      const old = this.rangeQuery(idx, idx);
      this.update(idx, val - old);
    }
  };
}

